window.DD_P=[{"id":"winter-run-3-things","cat":"장비","tone":"paper","w":["겨울 러닝","꼭 챙길 3"],"cap":"겨울 러닝 꼭 챙길 3가지 · 옷은 얇게 겹쳐","fine":"얇게 겹쳐 입고, 손·머리를 가리고, 체감온도를 먼저 보래요.","min":2,"k":[["얇게 겹쳐","두꺼운 한 벌 말고","질병관리청은 추운 날 내복이나 얇은 옷을 겹쳐 입으라고 안내해요.","질병관리청 2026","shirt"],["땀 빠지는 옷","안쪽은 이걸로","그런데 뛰면 땀이 나요. 그래서 땀을 빼 주는 옷으로 겹쳐 입으래요.","KidsHealth"],["손·머리 가리기","장갑·모자·목도리","게다가 장갑·목도리·모자로 손과 목, 머리를 따뜻하게 하래요.","질병관리청 2026"],["체감온도 먼저","나가기 전에 확인","나가기 전에 체감온도를 보고, 많이 추우면 밖 운동을 줄이래요.","질병관리청 2026"]],"sum":["얇은 옷을 겹쳐요","손·목·머리 가려요","체감온도 먼저 봐요"],"refs":["질병관리청 보도자료 2026.2.5, 「입춘 이후 갑작스러운 추위」 건강수칙","KidsHealth(Nemours), Safety Tips: Running"],"c":[],"qz":{"q":"겨울 러닝 옷, 두꺼운 한 벌? 얇게 겹쳐?","a":["두꺼운 한 벌","얇게 겹쳐"],"ans":1,"why":"얇은 옷을 겹쳐 입으라고 안내한대요."},"oc":"겨울에 뛸 때 옷은 몇 겹까지 입어요?"},{"id":"hot-day-run-3-things","cat":"런린이 가이드","tone":"black","w":["더운 날","러닝 3가지"],"cap":"여름 더운 날 러닝, 꼭 지킬 3가지","fine":"가장 더운 때는 피하고, 물은 미리, 모자와 밝은 옷이래요.","min":2,"k":[["더운 때 피하기","시간을 옮겨요","질병관리청은 가장 더운 시간대엔 야외 운동을 줄이고 시원한 곳에 있으래요.","질병관리청 2026","thermo"],["목마르기 전에","물은 미리미리","그래서 목이 마르지 않아도 규칙적으로 물을 자주 마시래요.","질병관리청 2026"],["모자·밝은 옷","물도 더 챙기기","게다가 모자를 쓰고 밝은색 옷을 입고, 물을 더 챙겨 가래요.","KidsHealth"]],"sum":["더운 시간은 피해요","물은 목마르기 전에","모자·밝은 옷 입어요"],"refs":["질병관리청 보도자료 2026.7.12, 첫 폭염중대경보 건강수칙","KidsHealth(Nemours), Safety Tips: Running"],"c":[],"qz":{"q":"더운 날 물, 언제 마시래요?","a":["목마를 때만","목마르기 전에도"],"ans":1,"why":"목마르지 않아도 규칙적으로 자주 마시래요."},"oc":"여름엔 보통 몇 시쯤 나가서 뛰어요?"},{"id":"running-break-fitness-loss","cat":"런린이 가이드","tone":"paper","w":["러닝 쉬면","체력 빠져?"],"cap":"러닝 쉬면 체력 얼마나 빠질까","fine":"3주 쉬면 조금, 8주면 꽤 빠져요. 그래도 실핏줄은 남는대요.","min":3,"k":[["7%","3주 쉬면 이만큼","꾸준히 뛰던 사람이 3주 쉬자 숨 쓰는 힘이 7% 줄었대요. 생각보다 천천히요.","Coyle 1984","week"],["피 −12%","먼저 줄어드는 건 피","가장 먼저 줄어드는 건 피 속 물이에요. 2~4주 쉬자 12% 줄었대요.","Coyle 1986"],["16%","8주쯤에서 멈춰요","56일째엔 16% 낮아진 채로 더는 안 떨어지고 머물렀대요.","Coyle 1984"],["그대로","실핏줄은 안 줄었어요","그래도 근육 속 실핏줄은 84일을 쉬어도 줄지 않았대요. 만든 길은 남아요.","Coyle 1984","heart"]],"sum":["2~4주 쉬면 피부터 줄어요","8주 쉬면 꽤 내려가요","만든 실핏줄은 오래 남아요"],"refs":["Coyle 외 1984, J Appl Physiol","Coyle·Hemmert·Coggan 1986, J Appl Physiol"],"c":[],"qz":{"q":"오래 쉬어도 안 줄어든 건?","a":["피의 물","실핏줄","숨 쓰는 힘"],"ans":1,"why":"근육 속 실핏줄은 84일을 쉬어도 안 줄었대요."},"oc":"러닝을 가장 오래 쉬어 본 게 얼마 동안이었어요?"},{"id":"same-pace-heart-rate-drop","cat":"몸속 이야기","tone":"paper","w":["꾸준히 뛰면","심박 줄어?"],"cap":"러닝 꾸준히 하면 심박수 언제부터 떨어질까","fine":"같은 속도의 심박은 석 달 안에 거의 다 내려가고, 체력은 더 올라요.","min":4,"k":[["−11회","같은 속도, 덜 뛰는 심장","주 3번 45분씩 1년 걷고 뛰자, 같은 세기에서 심장이 1분에 11번 덜 뛰었대요.","Scharhag-Rosenberger 2009","pulse"],["93%","석 달 안에 거의 다","그런데 줄어든 11번 가운데 93%는 처음 3개월 안에 이미 줄었대요.","Scharhag-Rosenberger 2009"],["11.8%","피가 먼저 늘어요","하루 2시간씩 열흘 넘게 운동하자 피의 물 성분이 11.8% 늘고 심장이 덜 뛰었대요.","Green 1991","cup"],["16%","체력은 더 올라요","대신 숨 쓰는 힘은 1년에 16% 늘었대요. 3개월 땐 그 가운데 52%만 늘었어요.","Scharhag-Rosenberger 2009"]],"sum":["심박은 석 달 안에 내려가요","심박 그대로여도 체력은 올라요","6개월쯤엔 자극 늘려 보기"],"refs":["Green 외 1991, Eur J Appl Physiol","Scharhag-Rosenberger 외 2009, Med Sci Sports Exerc"],"c":[],"qz":{"q":"같은 속도 심박, 언제 거의 다 내려갈까?","a":["1년 끝","첫 3개월"],"ans":1,"why":"줄어든 11번 중 93%가 첫 3개월 안에 나왔대요."},"oc":"같은 속도인데 덜 힘들다고 느낀 순간이 있었나요?"},{"id":"weekly-mileage-10-percent-rule","cat":"런린이 가이드","tone":"paper","w":["10%","규칙","진짜야?"],"cap":"러닝 거리 늘리기, 10% 규칙 지켜야 할까","fine":"10%를 넘겨도 부상률은 비슷했지만, 30% 넘게 늘리면 조심하래요.","min":4,"k":[["874명","초보 1년 지켜보기","달리기를 막 시작한 874명에게 GPS 시계를 채우고 1년을 지켜봤대요.","Nielsen 2014","watch"],["차이 없음","10% 넘겨도 비슷","그런데 10%를 넘겨 늘린 사람도 전체 부상률은 크게 다르지 않았대요.","Nielsen 2014"],["30%","2주에 30% 넘게는 조심","대신 2주에 30% 넘게 늘리면 무릎·정강이 부상이 좀 더 많은 편이었대요.","Nielsen 2014","shin"],["20.8≈20.3","천천히만 해도 비슷","게다가 13주 천천히 한 초보도 다친 비율은 20.8%, 보통 쪽은 20.3%였대요.","Buist 2008"]],"sum":["10%는 정답 아닌 대략값","2주에 30% 넘게 늘리지 않기","천천히만 한다고 안 다치진 않아요"],"refs":["Nielsen 외 2014, J Orthop Sports Phys Ther","Buist 외 2008, Am J Sports Med"],"c":[],"qz":{"q":"주간 거리 10% 넘기면 훨씬 더 다칠까?","a":["O","X"],"ans":1,"why":"10%를 넘겨도 전체 부상률은 크게 다르지 않았대요."},"oc":"한 주에 달리는 거리, 어떻게 늘려 가고 있어요?"},{"id":"running-cadence-step-rate-knee","cat":"런린이 가이드","tone":"paper","w":["걸음 늘리면","무릎 편해?"],"cap":"러닝 케이던스 올리면 무릎이 편해질까","fine":"같은 속도에서 걸음 수를 5~10% 늘리면 무릎 부담이 줄었대요.","min":3,"k":[["+5%","걸음 수만 살짝","같은 속도에서 걸음 수를 5%만 늘려도 무릎이 받는 부담이 줄었대요.","Heiderscheit 2011","steps"],["+10%","엉덩이까지 편해져요","10%를 늘리면 무릎에 더해 엉덩이가 받는 부담도 줄었대요.","Heiderscheit 2011"],["−10%","보폭을 넓히면","반대로 걸음 수를 10% 줄이자 엉덩이·무릎·발목 부담이 모두 크게 늘었대요.","Heiderscheit 2011"],["−14%","무릎뼈 뒤쪽 부담","다른 연구에서도 걸음을 10% 늘리자 무릎뼈 뒤에 걸리는 힘이 14% 줄었대요.","Lenhart 2014"]],"sum":["보폭은 짧게, 걸음은 촘촘히","평소보다 5~10%만 올리기","부상을 막는지는 아직 몰라요"],"refs":["Heiderscheit 외 2011, Med Sci Sports Exerc","Lenhart 외 2014, Med Sci Sports Exerc"],"c":[],"qz":{"q":"같은 속도, 걸음 수를 늘리면 무릎은?","a":["부담 ↓","부담 ↑"],"ans":0,"why":"걸음 수를 5%만 늘려도 무릎 부담이 줄었대요."},"oc":"달릴 때 보폭을 짧게 하는 편이에요, 길게 하는 편이에요?"},{"id":"start-running-after-50","cat":"런린이 가이드","tone":"paper","w":["50대 러닝","늦었어?"],"cap":"50대·60대 러닝 시작, 늦은 걸까","fine":"60대도 좋아지는 비율은 젊은 쪽과 비슷하고, 혈관은 석 달이면 반응한대요.","min":4,"k":[["나이 차이 없음","60대끼리 나눠 봐도","60~71세를 세 묶음으로 나눠도 좋아진 비율이 21%·19%·18%로 비슷했대요.","Kohrt 1991"],["17~65세","같은 운동 633명","17~65세가 똑같이 운동하니, 나이 든 쪽은 는 양은 적어도 오른 비율은 비슷했대요.","Skinner 2001","pulse"],["3개월","큰 혈관이 말랑해져요","게다가 앉아 지내던 50대가 석 달 걷자 큰 혈관이 운동해 온 또래만큼 말랑해졌대요.","Tanaka 2000"],["+6%","74세 허벅지도 커져요","74세쯤 남성들이 12주 자전거를 타자 허벅지 근육이 6% 커졌대요(작은 연구).","Harber 2012","scale"]],"sum":["좋아지는 비율은 나이와 별로","걷기 석 달에도 혈관이 반응","는 양 말고 비율로 보기"],"refs":["Kohrt 외 1991, J Appl Physiol","Skinner 외 2001, J Appl Physiol","Tanaka 외 2000, Circulation","Harber 외 2012, J Appl Physiol"],"c":[],"qz":{"q":"60대도 운동하면 젊은 쪽만큼 좋아질까?","a":["O","X"],"ans":0,"why":"60~71세도 좋아지는 비율이 젊은 쪽과 비슷했대요."},"oc":"늦게라도 꼭 시작해 보고 싶은 운동이 있나요?"},{"id":"exercise-non-responder-myth","cat":"러닝 잡지식","tone":"black","w":["운동해도","나만","안 늘어?"],"cap":"운동해도 체력이 안 느는 사람, 정말 있을까","fine":"'안 느는 사람'은 횟수나 세기를 올리자 거의 사라졌대요.","min":4,"k":[["5명 중 1명","안 는다는 사람들","권장량대로 해도 체력이 안 느는 사람이 5명 중 1명꼴이라는 말이 있었대요.","Montero·Lundby 2017"],["69% → 0%","횟수를 늘리면","그런데 주 1번 한 쪽은 69%가 '안 늘었다', 주 4~5번 한 쪽은 0%였대요.","Montero·Lundby 2017","week"],["주 2번 더","안 늘던 사람도 늘어요","안 늘던 사람들이 6주 동안 주 2번을 더 하자 모두 체력이 늘었대요.","Montero·Lundby 2017"],["38.5% → 0%","세게 하면","세기도 그래요. 적게·약하게 한 쪽은 38.5%가 안 늘고, 많이·세게는 0%였대요.","Ross 2015","pulse"]],"sum":["안 늘면 양·세기부터","주 1번은 안 늘 수도 있대요","더 하면 결국 늘었대요"],"refs":["Montero·Lundby 2017, J Physiol","Ross 외 2015, Mayo Clin Proc"],"c":[],"qz":{"q":"체력 안 느는 사람, 횟수를 늘리면?","a":["그래도 안 늘어","늘었어요"],"ans":1,"why":"6주 동안 주 2번을 더 하자 모두 체력이 늘었대요."},"oc":"운동해도 그대로라고 느낀 적, 혹시 있었어요?"},{"id":"running-habit-66-days","cat":"런린이 가이드","tone":"paper","w":["습관 되는데","며칠 걸려?"],"cap":"운동 습관 만드는 데 며칠 걸릴까","fine":"평균 66일, 사람마다 18~254일. 한 번 빼먹어도 괜찮대요.","min":4,"k":[["66일","21일이 아니래요","새 행동이 저절로 되기까지 평균 66일쯤 걸렸대요. '21일이면 습관'은 근거가 약해요.","Lally 2010","week"],["18~254일","사람마다 크게 달라요","빠른 사람은 18일, 느린 사람은 254일쯤 걸릴 거라고 나왔대요.","Lally 2010"],["한 번 빼먹어도","습관은 안 무너져요","그래도 한 번쯤 빼먹는 건 습관 만들기에 큰 영향이 없었대요.","Lally 2010 · Gardner 2012","steps"],["언제·어디서","계획을 적어 두면","그래서 언제·어디서 할지 적어 둔 쪽이 실제로 운동을 훨씬 많이 했대요.","Milne 2002"]],"sum":["습관은 두 달 넘게 잡기","빼먹으면 다음 날 다시","요일·시간·장소 적어 두기"],"refs":["Lally 외 2010, Eur J Soc Psychol","Gardner·Lally·Wardle 2012, Br J Gen Pract","Milne 외 2002, Br J Health Psychol"],"c":[],"qz":{"q":"습관 되는 데 평균 며칠쯤?","a":["66일","21일"],"ans":0,"why":"평균 66일쯤 걸렸대요. 21일은 근거가 약해요."},"oc":"지금 하는 운동, 몇 주째 이어 가고 있어요?"},{"id":"run-walk-vs-run-only-marathon","cat":"비교·대결","tone":"paper","img":"road","w":["걸으며 뛰면","기록 손해?"],"cap":"마라톤 중간에 걸으면 기록 손해일까","fine":"걷기를 섞어도 기록은 비슷했고, 근육 통증과 피로는 덜했대요.","min":3,"k":[["42명","걷기 섞기 vs 쭉 달리기","일반 러너 42명을 걷다 뛰는 쪽과 쭉 달리는 쪽으로 나눠 마라톤을 뛰게 했대요.","Hottenrott 2016","watch"],["4:14·4:07","기록은 비슷","걷기 섞은 쪽 4시간 14분, 쭉 달린 쪽 4시간 7분. 차이는 뚜렷하지 않았대요.","Hottenrott 2016"],["덜 아파요","끝나고 근육 통증","게다가 결승선 뒤 걷기를 섞은 쪽이 근육 통증과 피로를 덜 느꼈대요.","Hottenrott 2016","steps"],["9주 30분","초보도 걷다 뛰다","영국 초보 프로그램도 1분 뛰고 1분 30초 걷기로 시작해 9주 뒤 30분을 뛴대요.","NHS Couch to 5K"]],"sum":["걷기 섞어도 기록은 비슷","근육 통증은 걷뛰 쪽이 덜해요","초보는 1분 뛰고 걷기부터"],"refs":["Hottenrott 외 2016, J Sci Med Sport","NHS Couch to 5K 프로그램"],"c":[],"qz":{"q":"걷기 섞은 마라톤, 기록이 많이 늦을까?","a":["O","X"],"ans":1,"why":"4시간 14분과 4시간 7분, 차이가 뚜렷하지 않았대요."},"oc":"오래 달릴 때 중간에 걷는 것, 괜찮다고 생각해요?"},{"id":"side-stitch-right-side-food","cat":"런린이 가이드","tone":"black","w":["옆구리","콕콕","왜?"],"cap":"달릴 때 옆구리 통증, 왜 오른쪽이 많을까","fine":"오른쪽 옆구리가 가장 흔하고, 출발 직전에 많이 먹으면 더 잘 생겼대요.","min":3,"k":[["46%","오른쪽이 제일 많아요","옆구리가 아팠던 사람 중 46%가 오른쪽, 23%가 왼쪽이었대요.","Morton 2005"],["14%","어깨 끝이 아프기도","게다가 14%는 어깨 끝도 아팠대요. 옆구리가 아픈 사람에게서 더 흔했어요.","Morton·Callister 2000","shirt"],["나이 들수록 ↓","젊을수록 흔해요","나이가 많을수록 옆구리 통증을 덜 겪었다고 나왔대요.","Morton 2005"],["1~2시간 전","많이 먹으면","그리고 출발 1~2시간 전에 많이 먹은 사람이 더 잘 겪었대요.","Morton 2005","cup"]],"sum":["출발 1~2시간 전 과식 피하기","오른쪽 옆구리가 더 흔해요","원인은 아직 연구 중이래요"],"refs":["Morton 외 2005, J Sci Med Sport","Morton·Callister 2000, Med Sci Sports Exerc"],"c":[],"qz":{"q":"달릴 때 옆구리, 어느 쪽이 더 많을까?","a":["왼쪽","오른쪽"],"ans":1,"why":"46%가 오른쪽, 23%가 왼쪽이었대요."},"oc":"달리기 전에 물이나 음식은 어떻게 챙겨요?"},{"c":[],"id":"running-shoe-cushion-soft-vs-firm","cat":"장비","tone":"paper","w":["러닝화 쿠션","푹신해야","덜 다쳐?"],"cap":"러닝화 쿠션, 푹신한 게 부상에 나을까","fine":"딱딱한 신발 쪽이 더 다쳤지만, 가벼운 러너에게서만 뚜렷했대요.","min":3,"k":[["848명","쿠션만 다른 두 신발","러너 848명에게 쿠션만 다른 신발을 나눠 주고 6개월을 지켜봤대요.","Malisoux 2020","steps"],["1.52배","딱딱한 쪽이 더 다쳤어요","그런데 딱딱한 신발을 신은 쪽이 푹신한 쪽보다 1.52배 더 다치기 쉬웠대요.","Malisoux 2020"],["가벼운 러너","가벼운 러너만 차이","가벼운 러너는 딱딱한 신발에서 1.80배였고, 무거운 러너는 비슷했대요.","Malisoux 2020","scale"],["1.60배","충격이 빨리 오면","발이 닿을 때 충격이 빨리 몰려오는 사람이 1.60배 더 다쳤대요. 푹신하면 천천히 와요.","Malisoux 2021"]],"sum":["푹신함이 늘 정답은 아니에요","가벼우면 쿠션 쪽이 나았대요","한 연구 결과라 단정은 일러요"],"refs":["Malisoux·Delattre·Urhausen·Theisen 2020, Am J Sports Med (PMID 31877062)","Malisoux 외 2021, Front Sports Act Living 3:744658 (PMC8632264)"],"qz":{"q":"더 다치기 쉬웠던 신발은?","a":["딱딱한 신발","푹신한 신발"],"ans":0,"why":"딱딱한 쪽이 1.52배 더 다치기 쉬웠대요."},"oc":"푹신한 러닝화랑 단단한 러닝화 중 어느 쪽이 좋아요?"},{"c":[],"id":"two-pairs-running-shoes-rotation","cat":"장비","tone":"paper","w":["신발 2켤레","덜 다쳐?"],"cap":"러닝화 두 켤레 번갈아 신으면 덜 다칠까","fine":"신발을 번갈아 신은 사람이 덜 다쳤대요. 신발 덕인지는 아직 몰라요.","min":3,"k":[["0.614배","번갈아 신으면 덜 다쳐요","264명을 22주 지켜보니, 신발을 번갈아 신은 사람은 다칠 위험이 0.614배였대요.","Malisoux 2015","week"],["다른 운동","달리기만 하지 않기","게다가 달리기 말고 다른 운동을 더 한 사람도 덜 다쳤대요.","Malisoux 2015"],["1.72배","예전에 다쳤다면","대신 전에 다친 적이 있는 사람은 다칠 위험이 1.72배였대요.","Malisoux 2015","shin"],["5편 / 8편","예전 부상이 1순위","다른 연구 8편 중 5편에서도 「지난 1년 안에 다친 적」이 다칠 위험을 높였대요.","Saragiotto 2014"]],"sum":["두 켤레 번갈아 신기도 방법","다른 운동도 섞기","예전에 다친 곳은 천천히"],"refs":["Malisoux·Ramesh·Mann·Seil·Urhausen·Theisen 2015, Scand J Med Sci Sports (PMID 24286345)","Saragiotto 외 2014, Sports Med 44(8):1153-1163 (PMID 24809248)"],"qz":{"q":"신발을 번갈아 신으면 다칠 위험은?","a":["더 커졌어요","더 작았어요"],"ans":1,"why":"0.614배였대요. 신발 덕인지는 아직 몰라요."},"oc":"여러분은 러닝화 몇 켤레 번갈아 신어요?"},{"c":[],"id":"running-socks-cotton-blisters","cat":"장비","tone":"paper","img":"socks","w":["면 양말","물집 잘나?"],"cap":"러닝 양말, 면 양말 신으면 물집 잘 생길까","fine":"면보다 아크릴 양말에서 물집이 적고 작았대요. 대부분 발가락에 생겼어요.","min":4,"k":[["35명","면 vs 아크릴 양말","러너 35명이 실만 다른 양말을 신자, 아크릴(합성 섬유) 쪽 물집이 더 적고 작았대요.","Herring·Richie 1990","shirt"],["마찰·땀","물집이 생기는 이유","왜냐면 신발이 피부를 계속 문지르면 피부 사이에 물이 차서 생기거든요.","Knapik 2014"],["65%","물집은 발가락에","물집의 65%가 발가락에 생겼대요. 앞꿈치·뒤꿈치보다 훨씬 많았어요.","Scheer 2014","steps"],["76%","오래 뛸수록 늘어요","5일 동안 219km를 뛰는 대회에선 나흘째에 76%가 물집이 생겼대요.","Scheer 2014"]],"sum":["면보다 땀 덜 머금는 양말","발 크기에 맞는 신발","긴 거리는 조금씩 늘리기"],"refs":["Herring·Richie 1990, J Am Podiatr Med Assoc 80:63-71","Scheer 외 2014, J Am Podiatr Med Assoc (PMID 25275735)","Knapik 2014, J Spec Oper Med (PMID 24952049)"],"qz":{"q":"물집이 더 적었던 양말은?","a":["아크릴 양말","면 양말"],"ans":0,"why":"아크릴 쪽 물집이 더 적고 작았대요."},"oc":"달릴 때 양말은 따로 골라 신는 편인가요?"},{"c":[],"id":"smartwatch-steps-calories-accuracy","cat":"장비","tone":"paper","w":["워치 칼로리","믿어도 돼?"],"cap":"스마트워치 칼로리·걸음 수, 얼마나 맞을까","fine":"걸음 수와 심박은 꽤 맞는데, 칼로리는 가장 나은 기기도 27% 넘게 틀렸대요.","min":4,"k":[["27.4%","칼로리는 잘 못 맞춰요","손목 기기 7종을 비교하니, 칼로리는 가장 잘 맞춘 기기도 27.4% 틀렸대요.","Shcherbina 2017","watch"],["92.6%","가장 크게 틀린 기기","게다가 칼로리를 가장 크게 틀린 기기는 92.6%나 어긋났대요.","Shcherbina 2017"],["5% 안팎","심박은 꽤 맞아요","대신 심박은 꽤 잘 맞았대요. 자전거 땐 1.8%, 걸을 땐 5.5%만 틀렸어요.","Shcherbina 2017","pulse"],["−22.7%","손목형 걸음 수","걸음 수는 손목형이 실제보다 1.5~22.7% 적게 셌대요. 허리 만보계는 거의 맞았어요.","Case 2015"]],"sum":["칼로리 숫자는 참고만","걸음 수·심박은 흐름 보기용","같은 기기로 꾸준히 비교"],"refs":["Shcherbina 외 2017, J Pers Med (PMID 28538708)","Case·Burwick·Volpp·Patel 2015, JAMA 313(6):625-626"],"qz":{"q":"스마트워치가 가장 못 맞춘 건?","a":["심박","칼로리"],"ans":1,"why":"칼로리는 가장 나은 기기도 27.4% 틀렸대요."},"oc":"달릴 때 시계나 휴대폰으로 기록을 남기나요?"},{"c":[],"id":"barefoot-vs-light-shoes-100g","cat":"비교·대결","tone":"paper","img":"shoe","w":["맨발 러닝","덜 힘들까?"],"cap":"맨발 달리기 vs 러닝화, 뭐가 덜 힘들까","fine":"100g 무거워지면 약 1% 더 힘들고, 같은 무게면 신발 쪽이 덜 힘들었대요.","min":4,"k":[["차이 없음","맨발 vs 가벼운 신발","맨발과 가벼운 러닝화를 그냥 비교하면 힘든 정도는 비슷했대요.","Franz 2012"],["1%","100g마다","왜냐면 무게 때문이에요. 발에 100g씩 더할 때마다 힘이 약 1% 더 들었대요.","Franz 2012","scale"],["3~4%","같은 무게면 신발 쪽","그래서 맨발에 신발만큼 무게를 붙이자 신발 쪽이 3~4% 덜 힘들었대요.","Franz 2012"],["0.78%","3,000m 기록은","기록으로 보면 한 짝에 100g 무거울 때마다 3,000m가 0.78% 느려졌대요.","Hoogkamer 2016"]],"sum":["맨발이 꼭 덜 힘든 건 아니에요","같은 조건이면 가벼운 쪽","100g 차이는 1% 안팎"],"refs":["Franz·Wierzbinski·Kram 2012, Med Sci Sports Exerc (PMID 22367745)","Hoogkamer·Kipp·Spiering·Kram 2016, Med Sci Sports Exerc (PMID 27327023)"],"qz":{"q":"신발이 100g 무거워지면?","a":["약 1% 더 힘들어","차이 없어"],"ans":0,"why":"발에 100g씩 더할 때마다 힘이 약 1% 더 들었대요."},"oc":"맨발로 달려 보고 싶은 곳이 있다면 어디예요?"},{"c":[],"id":"soccer-vs-running-4-weeks","cat":"비교·대결","tone":"black","w":["축구 vs","러닝 4주"],"cap":"축구 vs 러닝, 체력은 어느 쪽이 더 늘까","fine":"4주 뒤엔 둘이 거의 같았고, 12주까지는 축구 쪽만 조금 더 올랐대요.","min":4,"k":[["+7% vs +6%","4주 뒤 숨 쓰는 힘","운동 안 하던 남성들이 4주 축구·달리기를 하자 숨 쓰는 힘이 7%, 6% 늘었대요.","Krustrup 2010","pulse"],["20% vs 1%","심장이 확 뛰는 시간","그런데 심장이 아주 세게 뛴 시간이 축구는 20%쯤, 달리기는 1%쯤이었대요.","Krustrup 2010"],["0.11초","짧은 질주는 축구 쪽","그래서인지 12주 뒤 30m 질주는 축구 쪽만 0.11초 빨라졌대요.","Krustrup 2010","steps"],["726번","방향을 이만큼 틀어요","프로 축구 선수는 한 경기에 방향을 726번쯤 튼다는 분석이 있어요.","Bloomfield 2007"]],"sum":["처음 4주는 둘 다 숨이 늘어요","몰아치는 운동 뒤엔 쉬는 날","섞어서 하는 것도 방법"],"refs":["Krustrup 외 2010, Eur J Appl Physiol 108:1247-1258 (PMID 20039057)","Bloomfield·Polman·O'Donoghue 2007, J Sports Sci Med 6:63-70"],"qz":{"q":"4주 뒤 숨 쓰는 힘, 누가 더 늘었을까?","a":["축구가 훨씬","거의 같아요"],"ans":1,"why":"축구 7%, 달리기 6%로 거의 같았대요."},"oc":"4주 동안 하나만 한다면 축구예요, 러닝이에요?"},{"c":[],"id":"foot-pronation-novice-neutral-shoe","cat":"런린이 가이드","tone":"paper","w":["발 안쪽","무너져도","괜찮대"],"cap":"발이 안쪽으로 무너지면 러닝화 따로 사야 할까","fine":"같은 러닝화를 신은 초보들은 발이 안쪽으로 기울어도 더 다치진 않았대요.","min":4,"k":[["927명","같은 신발로 1년","초보 927명에게 모두 같은 보통 러닝화를 신기고 1년을 지켜봤대요.","Nielsen 2014","week"],["250km","안쪽 기운 발도 괜찮아","그런데 250km를 달렸을 때, 발이 안쪽으로 기운 사람도 더 다치진 않았대요.","Nielsen 2014"],["−0.37","오히려 조금 적었어요","오히려 1,000km당 부상은 안쪽으로 기운 발 쪽이 0.37건 더 적었대요.","Nielsen 2014","steps"],["쿠션은?","발 모양보다 쿠션","다른 실험에선 딱딱한 신발 쪽이 더 다쳤대요. 발 모양보다 쿠션에서 차이가 났어요.","Malisoux 2020"]],"sum":["발 모양만으로 겁먹지 않기","거리는 천천히 늘리기","아프면 쉬고 전문가와 상의"],"refs":["Nielsen 외 2014, Br J Sports Med 48(6):440-447 (PMID 23766439)","Malisoux 외 2020, Am J Sports Med 48(2):473-480 (PMID 31877062)"],"qz":{"q":"발이 안쪽으로 기운 초보, 더 다쳤을까?","a":["O","X"],"ans":1,"why":"같은 신발로 250km를 달려도 더 다치진 않았대요."},"oc":"러닝화 고를 때 제일 먼저 보는 건 뭐예요?"},{"c":[],"id":"hard-workout-next-day-again","cat":"런린이 가이드","tone":"paper","w":["세게 뛴","다음 날","또 뛰어?"],"cap":"세게 뛴 다음 날, 또 뛰어도 될까","fine":"하루 뒤에도 근육 연료는 덜 찼고, 허벅지 뻐근함은 사흘 갔대요.","min":4,"k":[["27%","하루 뒤에도 덜 찼어요","축구 경기 뒤 잘 먹었는데도, 하루 뒤 근육 연료가 27% 덜 차 있었대요.","Krustrup 2011","cup"],["72시간","허벅지 뻐근함","게다가 허벅지 근육통은 72시간까지 남아 있었대요.","Krustrup 2011"],["3경기","한 주에 세 판이면","사흘만 쉬고 치른 가운데 경기 뒤 가장 지쳤대요. 질주 기록도 2~9% 떨어졌어요.","Mohr 2016","week"],["안 커졌어요","덜 풀렸는데 또 하면","그래도 팔 운동 실험에선 덜 풀린 채 또 해도 손상이 더 커지진 않았대요.","Nosaka·Clarkson 1995"]],"sum":["세게 한 다음 날은 가볍게","근육 연료는 하루 뒤도 덜 차요","아프면 쉬는 게 먼저"],"refs":["Krustrup 외 2011, Eur J Appl Physiol 111:2987-2995 (PMID 21448723)","Mohr 외 2016, Eur J Appl Physiol 116:179-193 (PMID 26377004)","Nosaka·Clarkson 1995, Med Sci Sports Exerc 27:1263-1269 (PMID 8531624)"],"qz":{"q":"축구 뒤 허벅지 근육통, 얼마나 갔을까?","a":["72시간까지","하루면 끝"],"ans":0,"why":"허벅지 근육통은 72시간까지 남아 있었대요."},"oc":"세게 운동한 다음 날엔 쉬어요, 가볍게라도 움직여요?"},{"c":[],"id":"first-two-weeks-why-easier","cat":"몸속 이야기","tone":"paper","w":["2주 만에","덜 힘든","이유"],"cap":"운동 시작 2주, 왜 벌써 덜 힘들까","fine":"며칠 만에 피의 물 성분이 늘고, 열흘쯤 지나면 심장이 덜 빨리 뛴대요.","min":4,"k":[["3일","피의 물이 먼저","하루 2시간씩 3일 운동하자 피의 물 성분이 20% 늘었다는 연구가 있어요.","Green 1990","cup"],["427mL","8일이면 이만큼","8일 자전거를 탄 뒤 피 속 물이 427mL 늘었대요. 적혈구는 그대로였어요.","Convertino 1980"],["10~12일","심장이 덜 빨리 뛰어요","그래서 10~12일 이어서 운동하자 같은 세기에서 심장이 덜 빨리 뛰었대요.","Green 1991","heart"],["47%","근육 연료를 아껴요","게다가 같은 운동 뒤 근육 연료가 47% 더 남아 있었대요. 아껴 쓰게 된 거예요.","Green 1991"]],"sum":["2주쯤 지나면 조금 편해져요","편해져도 거리는 천천히","연구는 하루 2시간이었어요"],"refs":["Green·Jones·Painter 1990, Med Sci Sports Exerc (PMID 2402209)","Convertino 외 1980, J Appl Physiol (PMID 6991463)","Green·Coates·Sutton·Jones 1991, Eur J Appl Physiol (PMID 1915326)","Green 외 1991, J Appl Physiol (PMID 1864784)"],"qz":{"q":"운동 며칠 만에 먼저 느는 건?","a":["붉은 피톨","피의 물 성분"],"ans":1,"why":"피의 물이 먼저 늘고, 붉은 피톨은 그대로였대요."},"oc":"같은 운동이 덜 힘들어진 건 시작하고 며칠쯤이었어요?"},{"c":[],"id":"ultramarathon-100km-foot-swelling","cat":"러닝 잡지식","tone":"paper","w":["100km","뛰면","발 커져?"],"cap":"울트라마라톤 100km 뛰면 발이 부을까","fine":"100km 뒤 발 부피는 평균 그대로였고, 물을 많이 마신 사람일수록 부었대요.","min":3,"k":[["−2.7%","평균은 거의 그대로","100km를 뛴 76명의 발 부피는 평균 2.7% 줄었지만, 뚜렷한 변화는 아니었대요.","Cejka 2012","steps"],["20·18·38","사람마다 달라요","그런데 76명 중 20명은 발이 커졌고, 18명은 그대로, 38명은 오히려 줄었대요.","Cejka 2012"],["7.64L","물을 많이 마실수록","물과 관계가 있었대요. 많이 마신 사람일수록 발이 더 부었어요. 평균 7.64L였어요.","Cejka 2012","cup"],["15분","짧게 뛴 뒤엔 반대","반대로 15분만 달린 뒤엔 걸은 뒤보다 발·발목이 더 부었다는 연구가 있어요.","Cloughley 1995"]],"sum":["발 부기는 사람마다 달라요","물을 많이 마실수록 부었대요","한 대회를 지켜본 연구예요"],"refs":["Cejka·Knechtle·Knechtle·Rüst·Rosemann 2012, J Int Soc Sports Nutr 9:11 (PMC3366912)","Cloughley·Mawdsley 1995, J Orthop Sports Phys Ther 22(4):151-154 (PMID 8535472)"],"qz":{"q":"100km 뒤 누구 발이 더 부었을까?","a":["물 많이 마신 쪽","물 적게 마신 쪽"],"ans":0,"why":"물을 많이 마실수록 발이 더 부었대요."},"oc":"100km 울트라마라톤, 언젠가 도전해 볼 마음 있어요?"},{"id":"tennis-1hour-real-play-time","cat":"비교·대결","tone":"paper","w":["테니스","1시간 중","몇 분 뛰어"],"cap":"테니스 1시간, 실제로 뛰는 건 몇 분일까","fine":"테니스 1시간 중 공이 오가는 시간은 13분쯤이라는 연구가 있어요.","min":4,"k":[["21.9%","공이 오가는 시간","선수 경기에서 공이 실제로 오간 시간은 21.9%였대요. 1시간이면 13분쯤이에요.","Fernandez-Fernandez 2007","watch"],["8.2초","랠리 한 번","랠리 한 번은 평균 8.2초, 사이에 쉬는 시간은 17.7초였대요.","Fernandez-Fernandez 2007"],["161회","그래도 심장은 바빠요","그래도 경기 중 심장은 1분에 평균 161번 뛰었대요.","Fernandez-Fernandez 2007","pulse"],["다리부터","스윙 힘은 다리에서","스윙 힘은 다리·몸통에서 만들어져 어깨와 팔로 전해진다고 알려져 있어요.","Kibler 1995"]],"sum":["1시간 중 공 오가는 건 13분","8초 움직이고 18초 쉬기","그래도 평균 심박은 161"],"refs":["Fernandez-Fernandez 외 2007, Br J Sports Med","Kibler 1995, Clin Sports Med"],"c":[],"qz":{"q":"테니스 1시간, 공이 오가는 시간은?","a":["거의 1시간","약 13분"],"ans":1,"why":"공이 실제로 오간 시간은 21.9%, 13분쯤이래요."},"oc":"테니스랑 러닝 중 1시간을 한다면 뭘 고를래요?"},{"id":"tennis-arm-bone-thicker","cat":"몸속 이야기","tone":"paper","w":["치는 팔","뼈가","더 굵대"],"cap":"테니스 치는 팔, 뼈가 더 굵어질까","fine":"자주 쓰는 쪽 팔뼈가 더 두껍다는 연구가 있어요. 일찍 시작할수록 차이가 컸대요.","min":4,"k":[["34.9%","치는 팔 뼈가 두꺼워요","프로 선수의 치는 쪽 팔뼈 겉벽이 반대쪽보다 남자 34.9%, 여자 28.4% 두꺼웠대요.","Jones 1977"],["3.2~4.6%","보통 사람은 조금","보통 여성은 양팔 뼈 차이가 3.2~4.6%뿐이었대요.","Kannus 1995","scale"],["15.5%","선수는 차이가 커요","그런데 테니스·스쿼시 여자 선수들은 위팔 쪽 양팔 차이가 15.5%였대요.","Kannus 1995"],["약 2배","일찍 시작할수록","게다가 사춘기 무렵이나 그 전에 시작한 선수는 이득이 약 2배였대요.","Kannus 1995","week"]],"sum":["치는 팔 뼈가 28~35% 두꺼워요","일찍 시작할수록 차이가 커요","뼈도 받는 힘에 맞춰 바뀌어요"],"refs":["Jones 외 1977, J Bone Joint Surg Am","Kannus 외 1995, Ann Intern Med"],"c":[],"qz":{"q":"테니스 치는 팔 뼈, 더 두꺼울까?","a":["O","X"],"ans":0,"why":"프로 남자 선수는 치는 쪽이 34.9% 두꺼웠대요."},"oc":"한쪽 팔이나 다리를 더 많이 쓰는 운동을 하고 있나요?"},{"id":"cheetah-vs-sled-dog","cat":"비교·대결","tone":"black","w":["치타","vs","썰매개"],"cap":"치타 vs 썰매개, 빠른 몸과 오래가는 몸","fine":"치타는 전속력을 몇 초, 썰매개는 490km를 사흘 가까이. 몸이 달라요.","min":4,"k":[["173m","치타 사냥은 짧아요","야생 치타가 쫓는 거리는 평균 173m쯤이었대요. 최고 속도는 1~2초만 냈어요.","Wilson 2013","watch"],["83%","치타 허벅지는 빨라요","치타 허벅지 근육의 83%가 빨리 힘을 내는 쪽이었대요.","Williams 1997"],["490km","썰매개는 사흘 가까이","반대로 알래스카 썰매개는 490km를 70시간에 걸쳐 평균 시속 7km로 완주했대요.","Hinchcliff 1997","thermo"],["−35℃","영하에서도 계속","경주 때 기온은 −35~−10℃였고, 썰매개는 아주 많은 에너지를 썼대요.","Hinchcliff 1997"]],"sum":["치타: 173m, 전속력은 몇 초","썰매개: 490km를 시속 7km로","빠른 몸과 오래가는 몸은 달라요"],"refs":["Wilson 외 2013, Nature","Williams 외 1997, J Comp Physiol B","Hinchcliff 외 1997, Am J Vet Res"],"c":[],"qz":{"q":"치타는 최고 속도를 얼마나 낼까?","a":["1~2초만","몇 시간씩"],"ans":0,"why":"최고 속도는 1~2초만 냈대요."},"oc":"짧고 빠르게랑 느리고 길게, 어떤 달리기가 더 좋아요?"},{"id":"breathing-steps-quadruped-vs-human","cat":"비교·대결","tone":"paper","w":["숨은","몇 걸음에","한 번?"],"cap":"달릴 때 숨은 몇 걸음에 한 번 쉴까","fine":"네발 동물은 걸음 하나에 숨 하나, 사람은 비율을 골라 쓴다는 연구가 있어요.","min":3,"k":[["1:1","네발 동물은 고정","토끼·개·말은 다리 한 번 움직일 때 숨 한 번, 1:1로 맞췄대요.","Bramble 1983","pulse"],["6가지","사람은 골라 써요","그런데 사람은 4:1, 3:1, 2:1 등 여러 비율을 골라 썼대요. 두 발이라서요.","Bramble 1983"],["2:1","가장 많이 쓰는 비율","그중엔 2:1을 가장 많이 쓰는 것 같대요. 다리 두 번에 숨 한 번꼴이에요.","Bramble 1983","steps"],["헐떡임","개는 숨으로 열을 식혀요","게다가 개는 헐떡이는 숨으로 몸의 열을 내보낸대요(개 3마리 연구).","Goldberg 1981"]],"sum":["네발 동물은 걸음마다 숨 하나","사람은 2:1을 많이 써요","정해진 정답 비율은 없대요"],"refs":["Bramble·Carrier 1983, Science","Goldberg·Langman·Taylor 1981, Respir Physiol"],"c":[],"qz":{"q":"달릴 때 숨 박자를 골라 쓰는 쪽은?","a":["네발 동물","사람"],"ans":1,"why":"사람은 4:1, 3:1, 2:1 등을 골라 썼대요."},"oc":"달릴 때 몇 걸음에 한 번 숨 쉬는지 세어 본 적 있어요?"},{"id":"to-failure-or-stop-early","cat":"비교·대결","tone":"paper","w":["근력운동","끝까지","해야 돼?"],"cap":"근력운동, 끝까지 해야 근육이 클까","fine":"무거우면 끝까지 안 가도 비슷, 가벼우면 끝까지 가야 컸다는 연구가 있어요.","min":4,"k":[["8.1 vs 7.7","무거운 무게일 때","무겁게 들면 끝까지 해도 8.1%, 미리 멈춰도 7.7%로 비슷하게 컸대요.","Lasevicius 2022","scale"],["7.8 vs 2.8","가벼운 무게일 때","그런데 가볍게 들면 끝까지 한 다리는 7.8%, 미리 멈추면 2.8%뿐이었대요.","Lasevicius 2022"],["12.4·6.7","무거울 때 세트당 횟수","무겁게는 끝까지 12.4번, 멈추면 6.7번. 횟수가 반인데도 크기 차이는 작았대요.","Lasevicius 2022","pulse"],["작은 것부터","작은 근육부터 써요","왜냐면 몸은 작은 근육 일꾼부터 켜고, 힘이 모자라면 큰 일꾼을 부른대요.","Henneman 1957"]],"sum":["무거우면 끝까지 안 가도 비슷","가벼우면 끝 근처까지 가기","작은 연구라 참고만 해요"],"refs":["Lasevicius 외 2022, J Strength Cond Res","Henneman 1957, Science"],"c":[],"qz":{"q":"가벼운 무게, 끝까지 들어야 클까?","a":["O","X"],"ans":0,"why":"끝까지는 7.8%, 미리 멈추면 2.8%뿐이었대요."},"oc":"근력 운동할 때 끝까지 짜내요, 여유를 남겨요?"},{"id":"born-to-run-hypothesis","cat":"러닝 잡지식","tone":"paper","vert":["달리려고","태어났나"],"cap":"사람은 원래 오래 달리게 태어났을까","fine":"오래 쫓는 사냥 덕에 달리는 몸이 됐다는 주장이 있어요. 아직 논쟁 중이에요.","min":5,"k":[["200만 년","오래 달리기 주장","오래 달리는 힘이 약 200만 년 전 생겼다는 주장이 2004년에 나왔어요.","Bramble·Lieberman 2004","hill"],["3시간 35분","더운 한낮에 쫓기","가장 더운 시간에 3시간 35분 동안 약 35km를 쫓은 사냥 기록이 있어요.","Liebenberg 2006"],["반론","너무 힘든 사냥 아냐?","그런데 달리기는 힘이 많이 들고, 이런 사냥 기록이 드물다는 반박도 있었어요.","Pickering·Bunn 2007"],["약 400건","사냥 기록 400건","대신 2024년 연구는 기록 약 400건을 모아, 꽤 쓸 만한 사냥법이었다고 봤어요.","Morin 2024","watch"]],"sum":["200만 년 전 시작이라는 주장","더운 한낮에 몇 시간 쫓기","찬반 논쟁은 아직 진행 중"],"refs":["Bramble·Lieberman 2004, Nature","Liebenberg 2006, Curr Anthropol","Pickering·Bunn 2007, J Hum Evol","Morin·Winterhalder 2024, Nat Hum Behav"],"c":[],"qz":{"q":"오래 쫓는 사냥 이야기, 결론 났을까?","a":["아직 논쟁 중","확정됐어요"],"ans":0,"why":"반박도 있어서 아직 논쟁 중이래요."},"oc":"오래 달리는 게 본능 같다고 느낀 적 있나요?"},{"id":"5km-average-time-parkrun","cat":"러닝 잡지식","tone":"paper","img":"road","w":["5km","평균은","몇 분?"],"cap":"5km 평균 기록은 몇 분일까","fine":"5km 기록의 한가운데는 29분 20초쯤이었대요. 걷는 사람도 많아요.","min":3,"k":[["29분 20초","5km 기록의 한가운데","영국 파크런 설문에서 5km 기록의 한가운데는 29분 20초쯤이었대요.","Haake 2022","watch"],["45,662명","설문에 답한 사람","매주 열리는 무료 5km 행사(파크런) 참가자 45,662명이 답했대요.","Haake 2022"],["32편","걷기만 해도 늘어요","게다가 걷기만 4주 넘게 한 연구 32편을 모아 보니, 숨 쓰는 힘이 늘었대요.","Murtagh 2015"],["기록 따로","좋아진 느낌은 비슷","그리고 걷는 사람도 빠른 사람도 몸과 마음이 좋아졌다는 느낌은 비슷했대요.","Haake 2022","heart"]],"sum":["5km 한가운데는 29분 20초","걷는 사람도 같은 코스를 가요","좋아진 느낌은 기록과 별개"],"refs":["Haake·Quirk·Bullas 2022, Br J Gen Pract","Murtagh 외 2015, Prev Med"],"c":[],"qz":{"q":"걷기만 해도 숨 쓰는 힘이 늘까?","a":["O","X"],"ans":0,"why":"걷기만 4주 넘게 한 연구 32편에서 늘었대요."},"oc":"요즘 목표로 하는 5km 기록이 있다면 몇 분이에요?"},{"id":"muscle-1kg-calories-per-day","cat":"러닝 잡지식","tone":"paper","w":["근육 1kg","하루","13kcal"],"cap":"근육 1kg 늘면 하루 몇 칼로리 더 쓸까","fine":"근육 1kg은 쉴 때 하루 13kcal쯤 쓴대요. 생각보다 작아요.","min":4,"k":[["13kcal","근육 1kg이 쉴 때","가만히 쉴 때 근육 1kg은 하루 13kcal쯤 쓴대요. 생각보다 작죠?","Wang 2010","scale"],["4.5kcal","지방 1kg은 더 적어","지방 1kg은 하루 4.5kcal쯤이래요. 근육보다도 훨씬 적어요.","Wang 2010"],["440kcal","심장·콩팥은 1kg당","대신 심장·콩팥은 1kg당 하루 440kcal를 쓴대요. 쉬지 않고 일하니까요.","Wang 2010"],["거의 그대로","근력운동만 했더니","그래서 근력운동만 한 쪽은 근육은 늘어도 몸무게는 거의 그대로였대요.","Willis 2012","week"]],"sum":["근육 1kg은 하루 13kcal쯤","심장·콩팥은 1kg당 440","살 빼기엔 유산소를 함께"],"refs":["Wang 외 2010, Am J Clin Nutr","Willis 외 2012, J Appl Physiol"],"c":[],"qz":{"q":"쉴 때 열량을 더 쓰는 건?","a":["지방 1kg","근육 1kg"],"ans":1,"why":"근육 1kg은 13kcal, 지방 1kg은 4.5kcal쯤이래요."},"oc":"근육을 더 붙이고 싶은 부위가 있다면 어디예요?"},{"id":"what-is-met-walk-vs-rope","cat":"러닝 잡지식","tone":"paper","w":["MET","그게","뭔데?"],"cap":"MET 뜻, 걷기와 줄넘기는 몇 MET일까","fine":"가만히 있을 때의 몇 배를 쓰는지가 MET예요. 줄넘기는 12쯤이래요.","min":3,"k":[["1 MET","가만히 있을 때가 1","가만히 있을 때 쓰는 힘을 1로 놓고, 운동은 그 몇 배인지 봐요.","MET 정의","heart"],["3 MET","1분에 100걸음쯤","1분에 100걸음쯤 걸으면 가만히 있을 때의 3배래요. 중간 세기예요.","Tudor-Locke 2019"],["6 MET","1분에 130걸음쯤","더 빨리, 1분에 130걸음쯤이면 6배래요. 센 운동 쪽으로 넘어가요.","Tudor-Locke 2019","steps"],["12 MET쯤","줄넘기는 훨씬 세요","줄넘기는 11.7~12.5배쯤이래요. 빨리 넘든 천천히 넘든 비슷했대요.","Town 1980"]],"sum":["MET는 가만히 있을 때의 몇 배","1분 100걸음이면 3배","줄넘기는 12배쯤"],"refs":["Tudor-Locke 외 2019, Int J Behav Nutr Phys Act","Town·Sol·Sinning 1980, Med Sci Sports Exerc"],"c":[],"qz":{"q":"줄넘기는 가만히 있을 때의 몇 배?","a":["12배쯤","3배","6배"],"ans":0,"why":"줄넘기는 11.7~12.5배쯤이래요."},"oc":"줄넘기랑 빠르게 걷기 중에 더 자주 하는 건 뭐예요?"},{"id":"workout-day-vs-rest-day-steps","cat":"비교·대결","tone":"black","w":["쉬는 날","걸음 수","확 줄어?"],"cap":"운동하는 날 vs 쉬는 날, 걸음 수 차이","fine":"30분 걷기 목표는 안 걷는 날 걸음이 확 줄었대요.","min":3,"k":[["9,505보","30분 걸은 날","'빠르게 30분 걷기'를 목표로 한 여성들은 걸은 날 하루 9,505보였대요.","Hultquist 2005","week"],["5,597보","그런데 안 걸은 날","그런데 30분을 안 걸은 날엔 5,597보로 뚝 떨어졌대요.","Hultquist 2005"],["10,159보","만 보 목표 쪽은","대신 '만 보' 목표 쪽은 4주 평균 10,159보였대요. 30분 쪽은 8,270보였어요.","Hultquist 2005","steps"],["빠르게","빠르기도 중요해요","게다가 같은 거리라도 빠르게 걸은 쪽이 숨 쓰는 힘이 더 늘었다는 연구도 있어요.","Duncan 1991"]],"sum":["안 걷는 날 걸음이 뚝","만 보 목표는 하루가 고르게","가끔은 빠르게 걷기"],"refs":["Hultquist·Albright·Thompson 2005, Med Sci Sports Exerc","Duncan·Gordon·Scott 1991, JAMA"],"c":[],"qz":{"q":"30분 걷기 목표, 안 걷는 날 걸음은?","a":["비슷해요","뚝 떨어져요"],"ans":1,"why":"걸은 날 9,505보, 안 걸은 날 5,597보였대요."},"oc":"쉬는 날에도 일부러 걷는 시간을 만드나요?"},{"id":"when-training-effects-start","cat":"런린이 가이드","tone":"paper","img":"cal","w":["운동 효과","언제부터?"],"cap":"운동 효과, 언제부터 나타날까","fine":"핏속 물은 며칠, 근육은 몇 주, 힘줄은 몇 달. 바뀌는 순서가 달라요.","min":4,"k":[["3일","핏속 물이 먼저","운동 3일 만에 핏속 물이 약 20% 늘었대요. 같은 세기에서 심장이 덜 뛰었대요.","Green 1990","pulse"],["10일","심장이 내보내는 피","10일쯤 지나면 힘껏 뛸 때 심장이 한 번에 내보내는 피가 늘었대요.","Mier 1997"],["35일","근육은 몇 주","근육은 더 느려요. 35일째에 허벅지가 6.5% 굵어졌대요. (작은 연구)","Seynnes 2007"],["3달","힘줄은 가장 늦게","힘줄은 3달은 지나야 단단해졌대요. 그래서 숨이 편해져도 거리는 천천히 늘리래요.","Kubo 2012","spring"]],"sum":["며칠이면 핏속 물이 늘어","근육은 몇 주 걸려요","거리는 천천히 늘리기"],"refs":["Green 외 1990, Med Sci Sports Exerc","Mier 외 1997, J Appl Physiol","Seynnes 외 2007, J Appl Physiol","Kubo 외 2012, Eur J Appl Physiol"],"c":[],"qz":{"q":"가장 늦게 바뀌는 건?","a":["핏속 물","근육","힘줄"],"ans":2,"why":"힘줄은 3달은 지나야 단단해졌대요."},"oc":"운동 효과, 언제쯤 느껴지길 기대하고 있어요?"},{"id":"jump-rope-warmup-for-runners","cat":"장비","tone":"paper","w":["뛰기 전","줄넘기 5분","효과 있어?"],"cap":"러닝 전 줄넘기 5분, 기록에 도움 될까","fine":"몸풀기 5분을 줄넘기로 바꾸면 3km 기록이 빨라졌다는 연구가 있어요.","min":4,"k":[["5분","몸풀기만 바꿨어요","러너들이 몸풀기 중 5분만 줄넘기로 바꿨대요. 주 2~4번, 10주 동안요.","García-Pinillos 2020","rope"],["3km","기록이 빨라졌대요","그랬더니 3km 기록이 빨라졌대요. 평소대로 한 쪽은 그대로였어요.","García-Pinillos 2020"],["튀는 힘","왜 빨라졌을까","통통 튀어 오르는 힘이 많이 는 사람일수록 기록도 더 줄었대요.","García-Pinillos 2020"],["39~114%","대신 발목은 힘들어","줄넘기는 발목이 받는 힘이 달리기보다 39~114% 컸대요. 처음엔 짧게 나눠 하래요.","Bruce 2020","spring"]],"sum":["몸풀기 5분을 줄넘기로","주 2~4번, 10주 동안","처음엔 짧게 나눠서"],"refs":["García-Pinillos 외 2020, Int J Sports Physiol Perform","Bruce 외 2020, Sports Biomech"],"c":[],"qz":{"q":"몸풀기를 줄넘기로, 3km 기록은?","a":["그대로","빨라졌어요"],"ans":1,"why":"10주 뒤 3km 기록이 빨라졌대요."},"oc":"달리기 전에 몸은 보통 어떻게 풀어요?"},{"id":"runners-high-not-just-endorphin","cat":"몸속 이야기","tone":"paper","w":["러너스 하이","엔도르핀?"],"cap":"러너스 하이는 엔도르핀 때문일까","fine":"엔도르핀만으로는 설명이 안 된다는 연구가 있어요. 아직 갈려요.","min":4,"k":[["63명","진통 물질을 막아도","뇌 속 진통 물질 신호를 막고 45분을 뛰게 했대요. 그래도 기분은 똑같이 좋아졌대요.","Siebers 2021","heart"],["2가지","다른 물질이 늘었어요","대신 피 속에서 몸이 만드는 다른 '기분 물질' 두 가지가 늘었대요.","Siebers 2021"],["사람·개","뛰는 동물만 늘어","사람과 개는 빨리 달린 뒤 이 물질이 늘었대요. 잘 안 뛰는 페럿은 안 늘었대요.","Raichlen 2012"],["2시간","반대 결과도 있어요","그런데 2시간 달린 선수 뇌에선 진통 물질이 일한 흔적도 보였대요. 아직 갈려요.","Boecker 2008","pulse"]],"sum":["진통 물질만이 답은 아니래요","다른 기분 물질도 늘어요","사람에선 아직 갈려요"],"refs":["Siebers 외 2021, Psychoneuroendocrinology","Raichlen 외 2012, J Exp Biol","Boecker 외 2008, Cereb Cortex"],"c":[],"qz":{"q":"러너스 하이, 엔도르핀 하나 때문일까?","a":["O","X"],"ans":1,"why":"진통 물질 신호를 막아도 기분이 똑같이 좋아졌대요."},"oc":"달리다 기분이 확 좋아진 순간, 느껴 본 적 있어요?"},{"id":"marathon-wall-glycogen","cat":"몸속 이야기","tone":"black","w":["마라톤 벽","왜 와?"],"cap":"마라톤 '벽'은 왜 생길까 · 몸속 연료가 바닥날 때","fine":"쌓아 둔 연료가 바닥나는 때가 벽이래요. 언제 오는지는 사람마다 달라요.","min":4,"k":[["5명 중 2명","벽을 만나는 사람","큰 마라톤에선 5명 중 2명 넘게 '벽'을 겪는대요. 몸속 연료가 바닥나는 때예요.","Rapoport 2010","steps"],["9명","연료가 많으면 오래","근육에 쌓아 둔 연료가 많을수록 지칠 때까지 더 오래 버텼대요. (작은 연구)","Bergström 1967"],["사람마다","벽이 오는 거리","그래서 벽이 오는 거리는 사람마다 달라요. 쌓아 둔 연료와 빠르기에 따라 바뀐대요.","Rapoport 2010","watch"],["1~2%","끝까지 못 가는 사람","큰 마라톤에선 1~2%가 결승선 전에 멈춘대요. 페이스와 보급은 미리 정해 두래요.","Rapoport 2010"]],"sum":["벽은 연료가 바닥날 때","오는 거리는 사람마다 달라","페이스·보급은 미리 정하기"],"refs":["Rapoport 2010, PLoS Comput Biol","Bergström 외 1967, Acta Physiol Scand"],"c":[],"qz":{"q":"마라톤 '벽'이 오는 거리, 다 같을까?","a":["O","X"],"ans":1,"why":"쌓아 둔 연료와 빠르기에 따라 사람마다 다르대요."},"oc":"오래 달리다 갑자기 다리가 무거워진 적 있나요?"},{"id":"running-hemolysis-footstrike","cat":"몸속 이야기","tone":"paper","w":["달리면","적혈구가","깨져?"],"cap":"달리면 적혈구가 깨진다? 발 구름 이야기","fine":"달리면 발 충격으로 적혈구가 조금 깨진대요. 양은 적은 편이래요.","min":3,"k":[["4배","달리기가 더 깨져요","같은 세기로 1시간씩 했더니, 깨진 적혈구 흔적이 자전거보다 달리기에서 4배 더 늘었대요.","Telford 2003","steps"],["발 구름","왜 달리기만 더?","이유는 발이 땅을 치는 충격 때문이래요. 다른 조건은 둘이 비슷했거든요.","Telford 2003"],["60km","울트라를 뛰고 나면","60km를 뛴 뒤에도 적혈구가 어느 정도 깨진 신호가 보였대요.","Lippi 2012","wave"],["크지 않대요","적혈구 수는 그대로","그래도 적혈구 수는 뚜렷한 변화가 없었대요. 깨지는 양은 아주 적은 편이래요.","Lippi 2012"]],"sum":["발 충격에 적혈구가 깨져요","자전거보다 달리기가 더","양은 아주 적은 편이래요"],"refs":["Telford 외 2003, J Appl Physiol","Lippi 외 2012, Blood Transfus"],"c":[],"qz":{"q":"깨진 적혈구 흔적이 더 는 운동은?","a":["달리기","자전거"],"ans":0,"why":"발이 땅을 치는 충격 때문에 4배 더 늘었대요."},"oc":"달릴 때 발뒤꿈치부터 닿아요, 앞쪽부터 닿아요?"},{"id":"cold-fingers-hunting-reaction","cat":"몸속 이야기","tone":"paper","w":["겨울 손가락","시렸다","따뜻해져"],"cap":"겨울에 뛰면 손가락이 시린 이유","fine":"차가운 손끝에 따뜻한 피가 몰려왔다 빠졌다 해요. '헌팅 반응'이래요.","min":4,"k":[["7.9분","찬물에 손을 넣으면","손을 찬물에 넣으면 평균 7.9분 뒤 따뜻한 피가 다시 몰려온대요.","Weller 2026","thermo"],["10.0℃","손끝이 차가워져야","그동안 손가락은 평균 10.0℃까지 식었대요. 충분히 차가워져야 반응이 시작된대요.","Weller 2026"],["몸통이 먼저","몸이 차면 반응 없음","그런데 몸 전체가 차가우면 이 반응이 거의 사라진대요. 몸통부터 지키는 거래요.","Daanen 2003"],["움직이면","운동이 피부를 데워요","대신 충분히 세게 움직이면 피부로 피가 더 가서 덜 식는대요.","Castellani 2021","steps"]],"sum":["손끝은 식었다 데워졌다 해요","몸이 차면 손끝은 뒤로","맨살은 덜 드러내기"],"refs":["Weller·Buczny·Daanen 2026, Temperature","Daanen 2003, Eur J Appl Physiol","Castellani 외 2021, Curr Sports Med Rep"],"c":[],"qz":{"q":"찬물 속 손, 따뜻한 피가 다시 올까?","a":["O","X"],"ans":0,"why":"평균 7.9분 뒤 따뜻한 피가 다시 몰려온대요."},"oc":"겨울에 달릴 때 장갑은 꼭 끼고 나가는 편이에요?"},{"id":"squat-running-economy","cat":"몸속 이야기","tone":"paper","w":["스쿼트 하면","더 빨라져?"],"cap":"러너가 스쿼트 하면 빨라질까","fine":"무거운 스쿼트 8주에 같은 속도가 덜 힘들어졌다는 연구가 있어요.","min":4,"k":[["5%","같은 속도가 덜 힘들게","러너들이 무거운 스쿼트를 8주 더했더니, 같은 속도가 5% 덜 힘들어졌대요.","Støren 2008","steps"],["21.3%","더 오래 버텼어요","그래서 힘껏 달려 지칠 때까지 버티는 시간도 21.3% 늘었대요.","Støren 2008"],["몸무게 그대로","체력은 그대로","몸무게나 숨 쓰는 힘은 그대로였대요. 같은 속도를 더 아껴 달리게 된 거래요.","Støren 2008","scale"],["32%","훈련 일부만 바꿔도","다른 연구에선 훈련 중 32%만 폭발적인 근력운동으로 바꿨더니 5km 기록이 좋아졌대요.","Paavolainen 1999"]],"sum":["스쿼트는 달리기를 아껴 줘요","훈련 일부를 근력으로","작은 연구라 참고로"],"refs":["Støren 외 2008, Med Sci Sports Exerc","Paavolainen 외 1999, J Appl Physiol"],"c":[],"qz":{"q":"러너가 스쿼트 8주, 같은 속도는?","a":["더 힘들어요","덜 힘들어요"],"ans":1,"why":"같은 속도에서 쓰는 산소가 5% 줄었대요."},"oc":"러닝 말고 하체 운동도 따로 하고 있어요?"},{"id":"carbs-per-hour-energy-gel","cat":"장비","tone":"paper","w":["뛰면서","탄수화물","얼마나?"],"cap":"마라톤 에너지 젤, 언제 얼마나 먹을까","fine":"1시간이면 헹구기만 해도, 2~3시간이면 한 시간 약 60g이 권장된대요.","min":4,"k":[["헹구기만","1시간 안쪽이면","1시간쯤이면 당 음료를 입에 머금었다 뱉기만 해도 기록이 빨라졌대요.","Carter 2004"],["약 60g","2~3시간 달릴 때","2~3시간 달리면 한 시간에 탄수화물 약 60g을 먹으라고 권한대요.","Jeukendrup 2014","cup"],["약 90g","아주 긴 대회라면","울트라처럼 더 길면 한 시간 약 90g이래요. 여러 종류 당을 섞어야 배에 덜 쌓여요.","Jeukendrup 2014"],["연습 때 먼저","배탈 줄이는 법","많이 먹으면 배가 불편할 수 있어요. 그래서 보급은 훈련 때 미리 연습하래요.","Jeukendrup 2014","shirt"]],"sum":["1시간이면 헹구기도 효과","2~3시간이면 한 시간 60g","보급은 훈련 때 먼저"],"refs":["Jeukendrup 2014, Sports Med","Carter 외 2004, Med Sci Sports Exerc"],"c":[],"qz":{"q":"1시간쯤 뛸 땐 당 음료를 어떻게?","a":["헹구기만 해도","꼭 다 마셔야"],"ans":0,"why":"입에 헹구고 뱉기만 해도 기록이 빨라졌대요."},"oc":"오래 달릴 때 중간에 뭘 먹는 편이에요?"},{"id":"winter-running-layers","cat":"장비","tone":"black","w":["겨울 러닝","몇 겹","입어?"],"cap":"겨울 러닝 옷 몇 겹 입어야 할까 · 레이어드","fine":"기본은 세 겹. 껴입고 출발하지 말고, 겉옷은 쉴 때 입으래요.","min":4,"k":[["3겹","속·중간·겉","추운 날은 세 겹이 기본이래요. 땀 빼는 속옷, 따뜻한 중간 옷, 바람 막는 겉옷이요.","Castellani 2021","shirt"],["껴입고 출발","흔한 실수","그런데 다 껴입고 출발하면 뛰다가 금방 너무 더워진대요.","Castellani 2021"],["겉옷은 쉴 때","뛸 땐 벗어도 돼요","그래서 비나 센 바람이 아니면 뛸 땐 겉옷을 벗고, 쉴 때 입으래요.","Castellani 2021"],["−4℃·1℃","잘 입으면 괜찮아","게다가 잘 입은 선수들은 −4℃와 1℃에서 가장 잘 뛰었대요. 더 춥거나 더우면 처졌대요.","Sandsund 2012"]],"sum":["속·중간·겉 세 겹","출발은 살짝 춥게","겉옷은 쉴 때 입기"],"refs":["Castellani 외 2021, Curr Sports Med Rep (ACSM 합의문)","Sandsund 외 2012, Eur J Appl Physiol"],"c":[],"qz":{"q":"겨울 러닝, 겉옷은 언제 입을까?","a":["뛸 때","쉴 때"],"ans":1,"why":"비·센 바람이 아니면 뛸 땐 벗고, 쉴 때 입으래요."},"oc":"여러분은 겨울 러닝 때 몇 겹 입고 나가요?"},{"id":"trekking-poles-knee-downhill","cat":"장비","tone":"paper","w":["스틱이","무릎","살려"],"cap":"등산 스틱, 내리막 무릎에 도움 될까","fine":"내리막에서 무릎에 걸리는 힘이 12~25% 줄었다는 연구가 있어요.","min":4,"k":[["12~25%","내리막 무릎 힘","내리막에서 스틱을 쓰면 무릎에 걸리는 힘이 12~25% 줄었대요. (작은 연구)","Schwameder 1999","hill"],["나눠 받기","왜 줄어들까","스틱이 힘을 나눠 받고, 몸이 살짝 앞으로 기울어 무릎 부담이 줄었대요.","Schwameder 1999"],["24·48시간","다음 날 덜 뻐근","게다가 진짜 산을 오르내린 연구에선 스틱 쪽이 24·48시간 뒤 근육통이 더 적었대요.","Howatson 2011"],["오르막도","덜 힘들게 느껴요","오르막에선 심박은 같았지만, 스틱 쪽이 덜 힘들다고 느꼈대요.","Howatson 2011","heart"]],"sum":["내리막엔 스틱 꺼내기","다음 날 덜 뻐근했대요","작은 연구라 참고로"],"refs":["Schwameder 외 1999, J Sports Sci","Howatson 외 2011, Med Sci Sports Exerc"],"c":[],"qz":{"q":"내리막에서 스틱 쓰면 무릎 힘은?","a":["줄어요","늘어요"],"ans":0,"why":"무릎에 걸리는 힘이 12~25% 줄었대요."},"oc":"등산할 때 스틱 쓰는 편이에요, 안 쓰는 편이에요?"},{"id":"kickboxing-5-weeks-vs-none","cat":"비교·대결","tone":"paper","w":["킥복싱","5주면?"],"cap":"킥복싱 5주 vs 안 한 5주, 체력 차이는?","fine":"숨 쓰는 힘은 13% 늘었지만 체지방은 그대로였대요. 식단은 따로 챙겨요.","min":4,"k":[["13.2%","5주 만에 숨 쓰는 힘","킥복싱을 주 3번, 5주 했더니 숨 쓰는 힘이 평균 13.2% 늘었대요.","Ouergui 2014","pulse"],["14.4%","유연성도 좋아져","같은 5주 동안 몸도 평균 14.4% 더 유연해졌대요.","Ouergui 2014"],["체지방 그대로","그런데 살은","그런데 체지방은 줄지 않았대요. 식단이나 다른 운동을 같이 챙겨야 한대요.","Ouergui 2014"],["1:2~1:4","세게 1, 쉬기 2~4","격투기 경기는 세게 1만큼 움직이면 2~4만큼 약하게 움직이거나 쉬는 리듬이래요.","Del Vecchio 2011","watch"]],"sum":["5주에도 숨 쓰는 힘 늘어","살은 식단을 같이","세게·쉬기를 번갈아"],"refs":["Ouergui 외 2014, Muscles Ligaments Tendons J","Del Vecchio 외 2011, Percept Mot Skills"],"c":[],"qz":{"q":"킥복싱 5주, 체지방도 줄었을까?","a":["O","X"],"ans":1,"why":"숨 쓰는 힘은 13.2% 늘었지만 체지방은 그대로였대요."},"oc":"러닝 말고 배워 보고 싶은 격투 운동이 있나요?"},{"id":"best-marathon-temperature","cat":"비교·대결","tone":"paper","w":["마라톤","몇 도가","제일 빨라?"],"cap":"마라톤 기록 잘 나오는 기온은 몇 도일까","fine":"약 4~10℃에서 가장 빨랐대요. 더울수록 느린 주자가 더 손해래요.","min":4,"k":[["3.8~9.9℃","가장 빨랐던 기온","179만 명의 마라톤 기록을 보니 3.8~9.9℃일 때 가장 빨리 달렸대요.","El Helou 2012","thermo"],["30.74%","더운 날엔 포기도","약 25℃였던 2007년 시카고 대회는 30.74%가 중간에 그만뒀대요.","El Helou 2012"],["4.5%","잘 뛰는 선수도","상위 선수도 더위 지수 20~25℃에선 대회 기록보다 4.5% 느려졌대요.","Ely 2007","watch"],["느린 주자","더위 손해가 더 커요","게다가 느린 주자일수록 더워질 때 더 많이 느려졌대요.","Ely 2007"]],"sum":["기록엔 서늘한 날이 유리","더운 날은 목표를 낮춰 잡기","느린 주자일수록 더위 조심"],"refs":["El Helou 외 2012, PLoS One","Ely 외 2007, Med Sci Sports Exerc"],"c":[],"qz":{"q":"마라톤이 가장 빨랐던 기온은?","a":["약 25℃","약 4~10℃"],"ans":1,"why":"179만 명 기록을 보니 3.8~9.9℃일 때 가장 빨랐대요."},"oc":"달리기 딱 좋은 날씨는 어떤 날이라고 생각해요?"},{"id":"marathon-taper-two-weeks","cat":"런린이 가이드","tone":"paper","img":"cal","w":["대회 전","얼마나","줄여?"],"cap":"마라톤 테이퍼링, 대회 2주 전 얼마나 줄일까","fine":"대회 2주 전부터 양은 줄이고 빠르기는 지키는 쪽이 좋았대요.","min":3,"k":[["2주","줄이는 기간","대회 전 훈련은 2주 동안 줄일 때 기록에 가장 좋았대요. 선수 연구를 모아 본 결과예요.","Bosquet 2007","week"],["41~60%","얼마나 줄일까","훈련량은 41~60%쯤 줄이래요. 한 번에 끊지 말고 점점 줄여요.","Bosquet 2007"],["세기는 그대로","빠르기는 지키기","대신 빠르기는 낮추지 않는 게 좋았대요. 짧게 뛰어도 평소 빠르기는 남겨요.","Bosquet 2007","watch"],["5분 32.4초","일반 러너도 효과","일반 러너도 3주 꾸준히 줄인 사람이 완주가 5분 32.4초 빨랐대요.","Smyth 2021"]],"sum":["대회 2~3주 전부터 줄이기","양은 줄이고 빠르기는 그대로","한 번에 끊지 말고 점점"],"refs":["Bosquet 외 2007, Med Sci Sports Exerc","Smyth·Lawlor 2021, Front Sports Act Living"],"c":[],"qz":{"q":"대회 2주 전, 빠르기도 낮출까?","a":["O","X"],"ans":1,"why":"양은 줄이고 빠르기는 지키는 쪽이 좋았대요."},"oc":"대회 앞두고 연습량을 줄이는 편이에요, 그대로 가요?"},{"id":"sub-two-hour-marathon","cat":"러닝 잡지식","tone":"paper","img":"road","w":["2시간","깨질까"],"cap":"마라톤 2시간 벽, 깨질 수 있을까","fine":"1991년 계산으론 1시간 57분대도 가능. 공인 기록은 2시간 0분 35초예요.","min":4,"k":[["1:57:58","1991년의 계산","몸이 모두 최고인 선수를 계산해 보니 1시간 57분 58초가 가능하대요.","Joyner 1991","watch"],["1:59:40","그런데 공인은 아냐","2019년 빈에서 2시간 안에 뛰었지만, 페이스메이커가 교대로 붙어 공인은 아니래요.","World Athletics 2019"],["2:00:35","지금 공인 기록","공인 세계 기록은 2023년 시카고 마라톤의 2시간 0분 35초예요.","World Athletics 2024"],["4%","신발도 한몫","게다가 탄소판 신발은 에너지를 4% 덜 쓰게 했대요. 신발 회사가 지원한 연구예요.","Hoogkamer 2018","spring"]],"sum":["계산으론 1시간 57분대","2시간 안쪽은 아직 비공인","신발이 힘을 4% 아꼈대"],"refs":["Joyner 1991, J Appl Physiol","World Athletics 2019, 빈 1:59 챌린지 보도","World Athletics 2024, 남자 마라톤 세계 기록 공인 발표","Hoogkamer 외 2018, Sports Med"],"c":[],"qz":{"q":"2019년 빈의 2시간 안 기록, 공인일까?","a":["O","X"],"ans":1,"why":"페이스메이커가 교대로 붙어 공인은 아니래요."},"oc":"마라톤 2시간 벽, 언제쯤 깨질 것 같아요?"},{"id":"why-marathon-42195","cat":"러닝 잡지식","tone":"paper","img":"road","w":["42.195","누가 정했냐"],"cap":"마라톤은 왜 42.195km일까","fine":"1908년 런던 올림픽 코스 길이가 그대로 굳어졌대요. 처음엔 약 40km였어요.","min":3,"k":[["약 40km","첫 올림픽 마라톤","1896년 아테네의 첫 올림픽 마라톤은 약 40km였대요.","World Athletics","watch"],["42,195m","1908년 런던 코스","그런데 1908년 런던 올림픽 코스가 윈저성에서 경기장까지 딱 42,195m였대요.","Olympedia"],["왕실 요청?","유명한 이야기는","왕실이 성 아래서 출발하게 해 달라 했다는 얘기는 근거가 약하대요.","Olympedia"],["1921년","정식 거리가 된 해","그리고 1921년에 42.195km가 정식 마라톤 거리로 정해졌대요.","Olympedia","steps"]],"sum":["첫 올림픽 마라톤은 약 40km","1908년 런던 코스가 기준","1921년에 정식 거리로 굳었대요"],"refs":["Olympedia, 1908 Olympic Games Marathon, Men","World Athletics, 1896 Olympic marathon 125th anniversary (2021)"],"c":[],"qz":{"q":"첫 올림픽 마라톤도 42.195km?","a":["O","X"],"ans":1,"why":"1896년 아테네 첫 대회는 약 40km였대요."},"oc":"풀코스·하프·10km 중에 제일 끌리는 거리는 뭐예요?"},{"id":"music-while-running","cat":"러닝 잡지식","tone":"paper","w":["음악 들으면","덜 힘들어?"],"cap":"음악 들으며 달리면 덜 힘들까","fine":"음악은 기분을 올리고 힘든 느낌을 줄인다는 분석이 있어요.","min":3,"k":[["덜 힘들게","음악을 들으면","음악을 들으면 기분이 좋아지고 덜 힘들게 느껴진대요. 연구 139편을 모아 본 결과예요.","Terry 2020","wave"],["심박은 그대로","심장은 속지 않아요","그런데 심박수는 그대로였대요. 몸은 똑같이 일하는데 덜 힘들게 느끼는 거예요.","Terry 2020"],["빠른 곡","어떤 곡이 좋을까","운동에는 느린 곡보다 빠른 곡이 더 도움이 됐대요.","Terry 2020"],["발 박자","걸음에 맞춘 비트","게다가 걸음 박자에 맞춘 음악을 들으면 더 오래 뛰었대요. 빠르기를 일정하게 지켜 줬대요.","Bood 2013","steps"]],"sum":["빠른 곡으로 목록 만들기","내 걸음 박자에 맞는 곡 고르기","밖에선 주변 소리가 들리게"],"refs":["Terry 외 2020, Psychol Bull","Bood 외 2013, PLoS One"],"c":[],"qz":{"q":"음악 들으면 심박수도 내려갈까?","a":["O","X"],"ans":1,"why":"심박은 그대로, 덜 힘들게 느끼는 거래요."},"oc":"달릴 때 음악 들어요, 아니면 조용히 뛰어요?"},{"id":"fat-burn-after-20min-myth","cat":"러닝 잡지식","tone":"paper","w":["지방은","20분 뒤","탄다며?"],"cap":"지방은 20분 뛰어야 타기 시작할까","fine":"지방은 처음부터 함께 쓰이고, 세기와 시간에 따라 비율이 바뀐대요.","min":4,"k":[["처음부터","지방은 바로 쓰여요","가볍게 움직일 때 몸속 지방이 가장 많이 꺼내진대요. 처음부터 함께 쓰이는 거예요.","Romijn 1993"],["64%","가장 많이 타는 세기","지방은 숨 쓰는 힘의 64%, 최대 심박의 74% 근처에서 가장 많이 탔대요.","Achten 2002","pulse"],["89%","너무 세면 거의 0","그런데 숨 쓰는 힘의 89%를 넘게 세게 뛰면 지방은 거의 안 쓰고 탄수화물을 쓴대요.","Achten 2002"],["−0.92kg","나눠 해도 괜찮아","게다가 운동을 여러 번 나눠 한 쪽이 몸무게가 0.92kg 더 줄었대요.","Murphy 2019"]],"sum":["20분 전에도 지방은 쓰여요","너무 세면 연료는 탄수화물","나눠 뛰어도 괜찮아요"],"refs":["Romijn 외 1993, Am J Physiol","Achten 외 2002, Med Sci Sports Exerc","Murphy 외 2019, Sports Med"],"c":[],"qz":{"q":"지방은 20분 지나야 쓰이기 시작할까?","a":["O","X"],"ans":1,"why":"지방은 처음부터 함께 쓰인대요."},"oc":"한 번 나가면 보통 몇 분쯤 달리다 들어와요?"},{"id":"stomach-ache-while-running","cat":"몸속 이야기","tone":"black","w":["달리다","배 아픈","이유"],"cap":"달리다 배 아픈 이유, 어떻게 줄일까","fine":"오래 달리면 배 불편함이 흔하대요. 그래도 장도 연습이 된대요.","min":4,"k":[["93%","긴 철인 경기 뒤","긴 철인 3종 경기에 나선 사람 93%가 배 불편함을 겪었대요.","Jeukendrup 2000"],["45%","보통 대회에서도","보통 달리기 대회 러너도 45%가 달리다 배가 불편한 적이 있대요.","ter Steege 2008","cup"],["예전에도?","겪어 본 사람이 또","그런데 예전에 배탈을 겪은 사람일수록 대회 중에 또 불편했대요.","Pfeiffer 2012"],["2주","장도 연습이 돼요","대신 달리며 젤을 2주 동안 매일 먹어 본 쪽은 배가 덜 불편했대요.","Miall 2018","week"]],"sum":["대회 날 처음 먹는 건 피하기","연습 때 달리며 먹고 마셔 보기","배탈이 잦았다면 더 천천히 늘리기"],"refs":["Jeukendrup 외 2000, Clin Sci","ter Steege 외 2008, Scand J Gastroenterol","Pfeiffer 외 2012, Med Sci Sports Exerc","Miall 외 2018, Scand J Med Sci Sports"],"c":[],"qz":{"q":"달리며 젤을 2주 연습하면 배는?","a":["덜 불편했어요","더 불편했어요"],"ans":0,"why":"매일 먹어 본 쪽은 배가 덜 불편했대요. 장도 연습이 돼요."},"oc":"달리기 전날 저녁은 주로 뭘 먹는 편이에요?"},{"id":"calf-cramp-while-running","cat":"몸속 이야기","tone":"paper","w":["뛰다가","종아리 쥐","왜 나?"],"cap":"달리다 종아리에 쥐 나는 이유","fine":"물·소금보다 빠른 속도와 예전에 쥐 났던 경험이 더 관련 있었대요.","min":3,"k":[["5명 중 1명","한 달 안에 쥐","트레일 러너 5명 중 1명이 지난 한 달 사이 쥐가 났대요. 가장 많은 곳은 종아리였어요.","Rizzo 2024","steps"],["차이 없음","물·소금 문제일까?","그런데 쥐 난 사람과 안 난 사람의 피 속 소금기, 빠진 몸무게는 차이가 없었대요.","Schwellnus 2011"],["빠른 속도","더 관련 있던 것","대신 쥐 난 사람들은 더 빨리 달렸고, 예전에도 쥐가 난 적이 많았대요.","Schwellnus 2011","pulse"]],"sum":["대회 날 평소보다 빨리 달리지 않기","쥐가 잘 나는 사람은 페이스 조심","물만으론 설명이 안 된대"],"refs":["Rizzo 외 2024, Braz J Phys Ther","Schwellnus 외 2011, Br J Sports Med"],"c":[],"qz":{"q":"종아리 쥐, 더 관련 있던 건?","a":["물·소금","빠른 속도"],"ans":1,"why":"핏속 소금은 차이 없고, 쥐 난 쪽이 더 빨리 달렸대요."},"oc":"달리고 나서 종아리 풀어 주는 나만의 방법이 있나요?"},{"id":"running-cadence-180","cat":"런린이 가이드","tone":"paper","w":["케이던스","180","정답?"],"cap":"러닝 케이던스 180, 꼭 맞춰야 할까","fine":"180은 선수 관찰에서 퍼진 숫자래요. 걸음 수는 속도와 키에 따라 달라요.","min":3,"k":[["180","어디서 나온 숫자?","1분에 180걸음은 1984년 올림픽 선수들을 본 한 코치의 관찰에서 퍼졌대요.","미시간대 2019 발표"],["155~203","선수끼리도 달라요","그런데 정상급 선수 20명도 1분에 155~203걸음으로 제각각이었대요.","Burns 2019","watch"],["빨라지면 ↑","속도 따라 바뀌어요","걸음 수는 속도에 따라 바뀌었대요. 빨리 달릴수록 늘고, 키가 크면 적었대요.","Burns 2019"],["+5~10%","바꾸려면 조금만","그래서 바꾼다면 조금만. 걸음 수를 5~10% 늘리자 무릎이 받는 충격이 줄었대요.","Heiderscheit 2011","shin"]],"sum":["180은 모두의 정답이 아니래요","내 걸음 수부터 세어 보기","바꾸려면 5% 안팎만 조금씩"],"refs":["University of Michigan 보도자료 2019 (Burns 연구 소개)","Burns 외 2019, J Appl Physiol","Heiderscheit 외 2011, Med Sci Sports Exerc"],"c":[],"qz":{"q":"케이던스 180, 모두 맞춰야 할까?","a":["O","X"],"ans":1,"why":"정상급 선수도 155~203걸음으로 제각각이었대요."},"oc":"1분에 몇 걸음 뛰는지 재 본 적 있어요?"},{"id":"stretching-before-run","cat":"런린이 가이드","tone":"paper","cap":"달리기 전 스트레칭, 꼭 해야 할까","fine":"늘이기는 짧게, 몸풀기는 움직이며. 부상 예방은 근력 운동 쪽이래요.","min":4,"k":[["60초","오래 늘이면 손해","뛰기 전 한 근육을 60초 넘게 늘이면 바로 뒤 운동이 4.6% 떨어졌대요.","Behm 2016","watch"],["+1.3%","움직이며 풀면","대신 다리 흔들기처럼 움직이며 풀면 운동이 1.3%쯤 나아졌대요.","Behm 2016"],["1,538명","부상은 비슷했어요","훈련병 1,538명을 보니 스트레칭을 해도 안 해도 다리 부상은 비슷했대요.","Pope 2000","shin"],["근력 운동","부상 예방은 이쪽","부상을 줄인 건 오히려 근력 운동이었대요. 연구 25개를 모아 본 결과예요.","Lauersen 2014"]],"sum":["가만히 늘이기는 60초 안쪽","뛰기 전엔 움직이며 몸풀기","부상 예방엔 근력 운동 더하기"],"refs":["Behm 외 2016, Appl Physiol Nutr Metab","Pope 외 2000, Med Sci Sports Exerc","Lauersen 외 2014, Br J Sports Med"],"c":[],"w":["뛰기 전","스트레칭","꼭 해?"],"qz":{"q":"뛰기 전 60초 넘게 늘이면?","a":["운동이 떨어져","운동이 나아져"],"ans":0,"why":"바로 뒤 운동이 4.6% 떨어졌대요."},"oc":"달리기 전 스트레칭, 매번 꼭 하는 편이에요?"},{"id":"carbon-plate-shoes","cat":"장비","tone":"paper","w":["카본화","신으면","빨라져?"],"cap":"카본화 신으면 정말 빨라질까","fine":"탄소판 신발이 힘을 약 4% 아꼈대요. 다만 빠른 속도에서 잰 값이에요.","min":4,"k":[["4%","같은 속도에 드는 힘","탄소판 신발을 신자 같은 속도에 드는 힘이 평균 4% 줄었대요. 18명 모두 줄었대요.","Hoogkamer 2018","spring"],["빠른 속도","잰 속도는 빨랐어요","그런데 시속 14~18km로 빠르게 뛸 때 잰 값이래요. 천천히 뛰면 다를 수 있어요.","Hoogkamer 2018"],["오르막엔 덜","언덕에선 효과가 작아","오르막·내리막에선 아끼는 힘이 평지보다 작았대요.","Whiting 2022"],["3분의 2","다 빨라지진 않아요","게다가 아낀 힘이 다 속도가 되진 않는대요. 아주 빠른 선수도 약 3분의 2만큼만요.","Kipp 2019","watch"]],"sum":["힘은 약 4% 덜 든다는 연구","빠른 속도·평지에서 잰 값","사람마다 아끼는 폭이 달라요"],"refs":["Hoogkamer 외 2018, Sports Med","Whiting 외 2022, J Sport Health Sci","Kipp 외 2019, Front Physiol"],"c":[],"qz":{"q":"카본화 효과, 오르막에서도 똑같을까?","a":["O","X"],"ans":1,"why":"오르막·내리막에선 아끼는 힘이 평지보다 작았대요."},"oc":"카본화, 신어 봤어요? 아니면 궁금하기만 해요?"},{"id":"compression-socks-running","cat":"장비","tone":"paper","img":"socks","w":["압박","양말","효과 있어?"],"cap":"압박 양말 신고 달리면 효과 있을까","fine":"기록은 거의 그대로, 다 뛴 뒤 다리 뻐근함엔 도움이 된다는 분석이 있어요.","min":3,"k":[["기록 그대로","신고 뛰어도","압박 양말을 신어도 마라톤·10km·5km 기록은 거의 그대로였대요.","Engel 2016","watch"],["뻐근함 ↓","효과는 뛴 다음","대신 다 뛴 뒤 다리 뻐근함을 줄이는 데는 효과가 컸대요.","Engel 2016"],["23편","회복엔 작지만 도움","회복 연구 23편을 모아 봐도 작지만 꽤 확실한 도움이 있었대요.","Brown 2017","scale"],["24시간+","근력 회복에 가장 커","특히 하루가 지나 근력이 돌아오는 데 효과가 가장 컸대요.","Brown 2017"]],"sum":["기록 올리려고 신는 건 아니래요","뛴 뒤 뻐근함엔 도움 될 수 있어요","너무 조여서 저리면 벗기"],"refs":["Engel 외 2016, Sports Med","Brown 외 2017, Sports Med"],"c":[],"qz":{"q":"압박 양말, 어디에 효과가 컸을까?","a":["기록 줄이기","뛴 뒤 뻐근함"],"ans":1,"why":"기록은 거의 그대로, 뛴 뒤 다리 뻐근함에 효과가 컸대요."},"oc":"압박 양말 신고 달려 본 적 있나요? 댓글로 알려 줘요!"},{"id":"sand-snow-vs-road-running","cat":"비교·대결","tone":"paper","w":["모래·눈길","얼마나","더 힘들어?"],"cap":"모래사장·눈길 달리기, 얼마나 더 힘들까","fine":"모래 위 달리기는 약 1.6배 힘이 들고, 새 눈길은 다져진 길보다 느려진대요.","min":3,"k":[["1.6배","모래 위 달리기","모래 위를 달리면 단단한 땅보다 힘이 1.6배 든대요. 발이 모래를 밀어내야 하거든요.","Lejeune 1998","wave"],["2.1~2.7배","걷기는 더 손해","그런데 모래 위 걷기는 2.1~2.7배나 들었대요. 달리기보다 손해가 커요.","Lejeune 1998"],["256초","새 눈은 더 느려","눈 덮인 오르막을 새 눈에선 256초, 발자국 난 길에선 225초 걸려 올랐대요.","Carceller 2019","hill"],["1.26배~","눈이 깊을수록 더","눈 위 걷기는 얕은 눈도 땅의 약 1.26배부터, 발이 빠질수록 힘이 더 든대요.","Richmond 2019"]],"sum":["모래에선 걷기보다 달리기가 덜 손해","눈길은 발자국 난 길로","같은 속도 말고 같은 숨으로"],"refs":["Lejeune 외 1998, J Exp Biol","Carceller 외 2019, High Alt Med Biol","Richmond 외 2019, Appl Ergon"],"c":[],"qz":{"q":"모래 위에서 더 손해 보는 건?","a":["걷기","달리기"],"ans":0,"why":"달리기는 1.6배, 걷기는 2.1~2.7배 힘이 들었대요."},"oc":"모래사장이랑 눈길 중에 어디서 달려 보고 싶어요?"},{"id":"heart-pounding-attraction","cat":"러닝 연애","tone":"black","w":["심장이","뛰면","설렌다?"],"cap":"같이 운동하면 설렌다? 심장 두근 효과","fine":"두근거린 직후엔 사람이 더 멋져 보였대요. 신나는 일을 같이 해요.","min":3,"k":[["내린 뒤 ↑","놀이기구 내린 사람","놀이공원에서 이성 사진을 보여 주자, 내린 사람이 탈 사람보다 더 매력 있다고 했대요.","Meston 2003","pulse"],["연인 옆 X","연인과 타면 달랐어요","그런데 연인과 같이 탄 사람은 타기 전과 내린 뒤 점수 차이가 없었대요.","Meston 2003"],["7분","신나는 일 딱 7분","커플이 7분 동안 새롭고 신나는 과제를 같이 하자 사이 점수가 더 올랐대요.","Aron 2000"],["지루함 ↓","이유는 지루함","설문에선 신나는 일을 같이 할수록 만족이 컸고, 지루함이 줄어든 덕으로 보였대요.","Aron 2000","heart"]],"sum":["두근거림이 설렘으로 번져요","연인 옆이면 효과가 달라요","새롭고 신나는 일을 같이"],"refs":["Meston·Frohlich 2003, Arch Sex Behav","Aron 외 2000, J Pers Soc Psychol"],"c":[],"qz":{"q":"놀이기구 내린 직후, 사진 속 이성은?","a":["더 매력 있게","덜 매력 있게"],"ans":0,"why":"내린 사람이 탈 사람보다 더 매력 있다고 했대요."},"oc":"같이 뛰고 나서 두근거렸던 적 있어요? 운동 탓이었을까요?"},{"id":"couple-workout-together","cat":"러닝 연애","tone":"paper","w":["같이","뛰면","오래가?"],"cap":"커플 운동, 같이 하면 오래갈까","fine":"짝이 운동을 시작하면 나도 따라 움직일 확률이 훨씬 높았대요.","min":3,"k":[["67%","짝이 시작하면 나도","짝이 운동을 새로 시작하자, 안 움직이던 남자의 67%가 운동을 늘렸대요.","Jackson 2015","steps"],["26%","짝이 그대로면","짝이 계속 안 움직이면 26%만 운동을 늘렸대요. 차이가 꽤 크죠.","Jackson 2015"],["3,261쌍","6년을 지켜보니","부부 3,261쌍을 6년 지켜보니, 아내 운동이 늘면 남편 운동도 같이 늘었대요.","Cobb 2016","week"],["234쌍","사이 좋은 부부는","사이에 만족하는 부부일수록 같이 먹고, 자고, 운동하는 일이 더 많았대요.","Wilson 2022"]],"sum":["짝이 뛰면 나도 뛰어요","6년 봐도 같이 움직여요","사이 좋을수록 함께해요"],"refs":["Jackson·Steptoe·Wardle 2015, JAMA Intern Med","Cobb 외 2016, Am J Epidemiol","Wilson·Novak 2022, Ann Behav Med"],"c":[],"qz":{"q":"짝이 운동을 새로 시작하면 남자는?","a":["67%가 따라 늘림","26%가 따라 늘림"],"ans":0,"why":"짝이 그대로면 26%, 새로 시작하면 67%였대요."},"oc":"같이 운동하는 짝 있어요? 누가 먼저 꼬셨나요?"},{"id":"first-5km","cat":"런린이 가이드","tone":"paper","w":["러닝 초보","5km","9주 계획"],"cap":"러닝 초보 5km, 9주 완주 계획","fine":"1분 뛰고 1분 30초 걷기부터. 주 3번이면 돼요.","min":4,"k":[["주 3회","쉬는 날 끼우기","일주일에 3번 뛰고, 사이사이 하루씩 쉬래요. 영국 초보 프로그램 얘기예요.","NHS Couch to 5K","week"],["1분+1분30초","1주차는 이렇게","1분 뛰고 1분 30초 걷기를 되풀이해요. 그렇게 20분을 채우면 끝이에요.","NHS Couch to 5K"],["15%","정강이를 조심","그런데 처음 뛰다 다친 사람 중엔 정강이 안쪽 통증이 15%로 제일 많았대요.","Nielsen 2014","shin"],["9개월","힘줄은 느려요","게다가 9개월 뛰자 숨은 편해졌는데 아킬레스건은 그대로였대요. 거리는 천천히 늘려요.","Hansen 2003"]],"sum":["주 3번, 쉬는 날 끼우기","1분 뛰고 1분 30초 걷기","거리는 천천히 늘리기"],"refs":["NHS Couch to 5K 프로그램","Nielsen 외 2014, PLoS One","Hansen 외 2003, J Appl Physiol"],"c":[["런린이3주차","걷기 섞으니까 진짜 버텨져요",12],["한강러너","9주 계획 저장해갑니다",5]],"qz":{"q":"초보 5km 계획, 일주일에 몇 번 뛸까?","a":["주 3번","매일"],"ans":0,"why":"주 3번 뛰고, 사이사이 하루씩 쉬래요."},"oc":"5km 처음 완주했을 때 몇 분 걸렸는지 기억나요?"},{"id":"winter-run","cat":"몸속 이야기","tone":"black","w":["폐가","얼까?"],"cap":"겨울 러닝, 찬 공기 마시면 폐가 얼까","fine":"폐는 안 얼어요. 조심할 건 목마름과 다 뛰고 멈출 때예요.","min":4,"k":[["31.6℃","폐는 안 얼어요","아주 찬 공기를 들이마셔도 폐 깊은 쪽에선 31.6℃까지 데워졌대요.","McFadden 1985","thermo"],["4~6%","식은 근육은 약해요","대신 근육은 1℃ 식을 때마다 순간 힘이 4~6%씩 줄었대요. 처음엔 천천히 데워요.","Bergh·Ekblom 1979"],["최대 40%","목마름이 숨어요","게다가 추우면 목마름을 최대 40% 덜 느꼈대요. 목이 안 말라도 물 한 컵 마셔요.","Kenefick 2004","cup"],["멈추는 순간","다 뛰고가 추워요","그리고 땀에 젖은 옷은 멈추면 몸을 빨리 식혀요. 들어가서 마른 옷부터 입어요.","ACSM 합의문 2021"]],"sum":["처음 1km는 천천히","목 안 말라도 물 한 컵","멈추면 바로 마른 옷"],"refs":["McFadden 외 1985, J Appl Physiol","Bergh·Ekblom 1979, Acta Physiol Scand","Kenefick 외 2004, Med Sci Sports Exerc","Castellani 외 2021, Curr Sports Med Rep"],"c":[],"qz":{"q":"겨울에 찬 공기 마시면 폐가 얼까?","a":["O","X"],"ans":1,"why":"폐 깊은 쪽에선 31.6℃까지 데워졌대요."},"oc":"겨울에도 밖에서 뛰어요, 아니면 실내로 가요?"},{"id":"gym-vs-run","cat":"비교·대결","tone":"paper","img":"cal","w":["헬스 vs","러닝","뭐가 먼저?"],"cap":"헬스 vs 러닝, 몸이 먼저 바뀌는 곳은?","fine":"먼저 바뀌는 곳이 달라요. 결론은 둘 다.","min":5,"k":[["며칠","러닝은 피부터","운동 시작 며칠 만에 피의 양이 늘고, 심장이 덜 뛰었다는 연구가 있어요.","Green 1990·1991","pulse"],["3~5주","헬스는 뇌가 먼저","근력운동 처음 3~5주는 근육보다 신경이 쓰는 법을 배운 덕이 컸대요.","Moritani 1979"],["8개월","살은 유산소 쪽","8개월 실험에서 몸무게는 유산소 쪽이 더 줄고, 근육은 근력운동 쪽이 더 늘었대요.","Willis 2012","scale"],["13kcal","근육 1kg의 하루","그런데 근육 1kg이 쉬며 쓰는 열량은 하루 약 13kcal래요. 근육만으론 어려워요.","Wang 2010"]],"sum":["러닝은 피·심장이 먼저","헬스는 뇌가 먼저 배워요","둘 다 섞어서 하기"],"refs":["Green 외 1990·1991","Moritani·deVries 1979, Am J Phys Med","Wang 외 2010, Am J Clin Nutr","Willis 외 2012, J Appl Physiol"],"c":[["헬린이","저는 둘 다 섞는 중이에요",3]],"qz":{"q":"8개월 실험, 몸무게가 더 준 쪽은?","a":["근력운동","유산소"],"ans":1,"why":"몸무게는 유산소 쪽이 더 줄었대요."},"oc":"헬스랑 러닝 중에 하나만 고르라면 뭘 할래요?"},{"id":"age-run","cat":"비교·대결","tone":"paper","w":["나이별로","달리기","몸 차이"],"cap":"20대·40대·60대가 같이 뛰면 몸은?","fine":"근육통은 의외로 젊은 쪽이, 좋아지는 비율은 셋이 비슷.","min":5,"k":[["208−0.7×나이","최고 심박 공식","최고 심박은 대략 208−0.7×나이래요. 220−나이는 나이 들수록 낮게 잡혀요.","Tanaka 2001","pulse"],["젊은 쪽","근육통은 젊은 쪽이","운동 뒤 근육통은 오히려 젊은 쪽이 더 컸대요. 연구 36편을 모아 보니 그랬어요.","Fernandes 2025"],["17.8:7.7","나이보다 '처음'","1,000시간당 초보는 17.8건, 경험자는 7.7건 다쳤대요. 나이보다 처음이 문제예요.","Videbæk 2015","shin"],["+24%","60대도 똑같이 늘어요","그래도 60~71세가 9~12개월 뛰자 심폐 능력이 24% 늘었대요. 젊은 쪽과 비슷해요.","Kohrt 1991"]],"sum":["속도는 내 숨에 맞추기","처음 몇 주는 정강이 조심","몇 살이든 좋아져요"],"refs":["Tanaka 외 2001, J Am Coll Cardiol","Fernandes 외 2025, J Aging Phys Act","Videbæk 외 2015, Sports Med","Kohrt 외 1991, J Appl Physiol"],"c":[["마흔둘러너","45세 이야기 보고 바로 나갑니다",14]],"qz":{"q":"운동 뒤 근육통, 누가 더 컸을까?","a":["젊은 쪽","나이 든 쪽"],"ans":0,"why":"연구 36편을 모아 보니 오히려 젊은 쪽이 더 컸대요."},"oc":"같이 뛰어 보고 싶은 가족이나 친구가 있나요?"},{"id":"animal-vs-human","cat":"러닝 잡지식","tone":"paper","w":["치타는","못 이겨도"],"cap":"동물 vs 사람, 오래 달리기는 누가 이길까","fine":"100m는 꼴찌. 길게 가면 이야기가 달라요.","min":4,"k":[["시속 93km","치타는 짧게 빨라요","치타는 시속 93km까지 내요. 그래도 사냥 추격은 평균 173m쯤에서 끝났대요.","Wilson 2013","watch"],["엉덩이","뛸 때 켜지는 근육","대신 사람은 뛸 때 엉덩이 근육이 크게 일해요. 몸이 앞으로 안 넘어지게 잡아요.","Lieberman 2006"],["2:1","숨 박자를 골라요","게다가 네발 동물은 한 걸음에 숨 한 번이지만, 사람은 두 걸음에 한 번을 많이 쓴대요.","Bramble 1983","pulse"],["29분 20초","보통 사람의 5km","그래서 보통 사람 4만 5천 명의 5km 기록은 딱 가운데가 29분 20초였대요.","Haake 2022"]],"sum":["짧게 뛰면 동물이 이겨요","길게 가면 사람 차례","숨은 걸음에 맞춰 세기"],"refs":["Wilson 외 2013, Nature","Lieberman 외 2006, J Exp Biol","Bramble·Carrier 1983, Science","Haake 외 2022, BJGP"],"c":[],"qz":{"q":"치타의 사냥 추격, 길게 갈까?","a":["오래 가요","짧게 끝나요"],"ans":1,"why":"평균 173m쯤에서 끝났대요."},"oc":"동물이랑 5km 겨룬다면 어떤 동물은 이길 것 같아요?"},{"id":"marathon-body","cat":"몸속 이야기","tone":"paper","img":"road","w":["42.195","몸속은?"],"cap":"마라톤 42.195km, 몸속에서 생기는 일","fine":"탄수화물, 물, 내리막. 세 가지를 알면 덜 무너져요.","min":5,"k":[["처음 몇 분","몸이 따라오는 시간","뛰기 시작하면 숨 쓰는 양이 몇 분에 걸쳐 올라가요. 그래서 초반은 천천히.","Whipp 1972","pulse"],["134→157분","중간에 먹으면","뛰는 중에 탄수화물을 먹자 지치는 때가 134분에서 157분으로 늦춰졌대요.","Coyle 1983"],["내리막","허벅지가 버틸 때","근육이 늘어나며 버틸 때 근육통이 더 컸대요. 내리막에선 서두르지 않기.","Newham 1983"]],"sum":["초반은 천천히","중간중간 탄수화물","목마를 때 몇 모금씩"],"refs":["Whipp·Wasserman 1972, J Appl Physiol","Coyle 외 1983, J Appl Physiol","Newham 외 1983, J Neurol Sci"],"c":[["숫자덕후","134분→157분 보고 젤 챙겨요",9]],"qz":{"q":"마라톤 중 탄수화물 먹으면 지치는 때는?","a":["늦춰져요","빨라져요"],"ans":0,"why":"134분에서 157분으로 늦춰졌대요."},"oc":"풀코스 마라톤, 언젠가 뛰어 볼 생각 있어요?"},{"id":"walk-vs-run","cat":"비교·대결","tone":"paper","w":["걸을까","뛸까"],"cap":"걷기 vs 달리기, 몸속에서 바뀌는 곳","fine":"달리면 심장이 크게 바뀌고, 실핏줄은 걷기·달리기 둘 다 늘어요.","min":4,"k":[["방이 넓어져요","달리기는 심장부터","오래 달린 선수의 심장은 안쪽 방이 넓어지고 벽도 따라 두꺼워진대요.","Pluim 2000","heart"],["+20%","실핏줄은 둘 다","8주 꾸준히 운동하자 허벅지 실핏줄이 20% 늘었대요. 걷기든 달리기든 쌓일수록 더.","Andersen 1977"]],"sum":["달리는 날엔 심장이 일해요","실핏줄은 걷든 뛰든 늘어요","섞어서, 내 몸에 맞게"],"refs":["Pluim 외 2000, Circulation","Andersen·Henriksson 1977, J Physiol"],"c":[],"qz":{"q":"8주 운동하면 허벅지 실핏줄은?","a":["줄어요","그대로","늘어요"],"ans":2,"why":"8주 꾸준히 운동하자 20% 늘었대요."},"oc":"요즘은 걷기가 더 많아요, 달리기가 더 많아요?"},{"id":"jump-rope","cat":"비교·대결","tone":"black","w":["줄넘기","vs","달리기"],"cap":"줄넘기 vs 달리기, 뭐가 더 힘들까","fine":"한 번은 줄넘기가 더 힘들어요. 오래 가는 힘은 달리기.","min":4,"k":[["고강도","줄넘기는 힘든 쪽","줄넘기는 천천히 해도 빨리 해도 꽤 힘든 운동 쪽으로 나왔대요.","Town 1980","rope"],["최대 2배","발목이 더 버텨요","줄넘기는 착지할 때 발목이 받는 힘이 달리기보다 많게는 두 배쯤 크대요.","Bruce 2020"],["달리기 쪽","오래 가는 힘은","대신 오래 달리는 기록은 줄넘기로 생각만큼 안 올랐대요. 자꾸 걸려 멈춰서라고 봐요.","Chen 2025","watch"],["5분","몸풀기만 줄넘기로","그래서 러너들이 몸풀기 5분을 줄넘기로 바꾸자 10주 뒤 3km 기록이 빨라졌대요.","García-Pinillos 2020"]],"sum":["줄넘기 1시간은 나눠서","몸이 가벼워도 조금씩","달리기 전 줄넘기 5분"],"refs":["Town 외 1980, Med Sci Sports Exerc","Bruce 외 2020, Sports Biomech","García-Pinillos 외 2020, Int J Sports Physiol Perform","Chen 외 2025"],"c":[],"qz":{"q":"착지할 때 발목이 더 버티는 쪽은?","a":["줄넘기","달리기"],"ans":0,"why":"줄넘기가 많게는 달리기보다 두 배쯤 크대요."},"oc":"줄넘기를 마지막으로 해 본 게 언제였나요?"},{"id":"trail-run","cat":"러닝 잡지식","tone":"paper","img":"shoe","w":["흙길이","더 편해?"],"cap":"트레일 러닝, 산길에서 몸이 하는 일","fine":"눈은 2~3걸음 앞, 아주 가파르면 걸어도 돼요.","min":4,"k":[["1.5초 앞","눈이 먼저 읽어요","험한 길에선 눈이 2~3걸음, 약 1.5초 앞을 미리 훑는대요.","Matthis 2018","hill"],["갈려요","흙길이 늘 편할까","그런데 흙길이라고 충격이 꼭 적진 않대요. 길보다 속도가 더 크게 작용했대요.","Boey 2017"],["무릎·정강이","산길에서 많이 다쳐요","트레일 러너 152명을 30주 지켜보니 무릎·정강이를 가장 많이 다쳤대요.","Viljoen 2021","shin"],["8.45%","가파르면 걸어요","그래서 아주 가파른 오르막은 뛰는 것보다 빨리 걷는 게 힘이 8.45% 덜 들었대요.","Giovanelli 2016"]],"sum":["가파른 오르막은 걸어도 OK","눈은 2~3걸음 앞","최근 다쳤다면 더 천천히"],"refs":["Matthis 외 2018, Curr Biol","Giovanelli 외 2016, J Appl Physiol","Boey 외 2017, Sports Biomech","Viljoen 외 2021, IJERPH"],"c":[],"qz":{"q":"아주 가파른 오르막, 뛰는 게 나을까?","a":["뛰기","빨리 걷기"],"ans":1,"why":"빨리 걷는 게 힘이 8.45% 덜 들었대요."},"oc":"산길을 달려 본다면 어느 산에서 해 보고 싶어요?"},{"id":"triathlon","cat":"몸속 이야기","tone":"paper","w":["철인 3종","몸속은?"],"cap":"철인 3종, 종목마다 몸속에서 생기는 일","fine":"진짜 고비는 종목이 바뀌는 순간.","min":5,"k":[["1.5·40·10","올림픽 코스","수영 1.5km, 자전거 40km, 달리기 10km를 쉬지 않고 이어서 해요.","World Triathlon","wave"],["192 vs 200","수영은 심장이 덜 뛰어요","같은 사람도 수영할 땐 최고 심박이 달리기보다 7번쯤 낮았대요.","Olstad 2019"],["1.6~11.6%","자전거 뒤 달리기","자전거 바로 뒤엔 같은 속도로 뛰어도 힘이 1.6~11.6% 더 든대요.","Millet·Vleck 2000"],["5분","어색함은 금방 가요","바뀐 달리기 자세는 대개 5분 안에 돌아온대요. 사람마다 다르긴 해요.","Bonacci 2010","watch"]],"sum":["종목 바뀔 때가 고비","자전거 마지막은 가볍게","달리기 첫 5분은 천천히"],"refs":["World Triathlon 코스 거리","Olstad 외 2019","Millet·Vleck 2000, Br J Sports Med","Bonacci 외 2010"],"c":[],"qz":{"q":"자전거 바로 뒤 달리기, 더 힘들까?","a":["O","X"],"ans":0,"why":"같은 속도로 뛰어도 힘이 1.6~11.6% 더 든대요."},"oc":"수영·자전거·달리기 중에 제일 자신 있는 건 뭐예요?"},{"id":"soccer-vs-run-90min","cat":"비교·대결","tone":"paper","w":["축구 vs","러닝 90분","몸 차이"],"cap":"축구 90분 vs 러닝 90분, 몸은 어떻게 다를까","fine":"축구는 꺾고 터지는 몸을, 러닝은 오래 버티는 몸을 써요.","min":4,"k":[["726번","한 경기에 방향 틀기","프로 축구 선수는 한 경기에 방향을 726번쯤 튼대요. 러닝은 같은 걸음을 되풀이해요.","Bloomfield 2007"],["2~2.9배","디딜 때마다","달릴 때 한 발 디딜 때마다 몸무게의 2.0~2.9배 힘이 걸린대요.","Nilsson·Thorstensson 1989","shin"],["72시간","회복엔 사흘 가까이","축구 경기 뒤 순간 힘은 72시간까지 떨어져 있었대요. 근육통은 하루 뒤가 제일 심했어요.","Ispirlidis 2008"],["+9%","석 달 뒤 허벅지","12주 해 보니 숨 쓰는 힘은 둘 다 늘고, 허벅지 근육은 축구 쪽만 9% 늘었대요.","Krustrup 2010","steps"]],"sum":["세게 찬 다음 날은 가볍게","회복엔 사흘쯤","축구·러닝·쉬는 날 섞기"],"refs":["Bloomfield 외 2007, J Sports Sci Med","Nilsson·Thorstensson 1989, Acta Physiol Scand","Ispirlidis 외 2008, Clin J Sport Med","Krustrup 외 2010, Eur J Appl Physiol"],"c":[],"qz":{"q":"축구 선수는 한 경기에 방향을 많이 틀까?","a":["O","X"],"ans":0,"why":"한 경기에 방향을 726번쯤 튼대요."},"oc":"공 차며 뛰는 쪽이 좋아요, 그냥 달리는 쪽이 좋아요?"},{"id":"hiking-vs-running-downhill","cat":"비교·대결","tone":"paper","w":["등산 하산","더 힘들어?"],"cap":"등산 vs 러닝, 내려올 때 무릎과 몸은 어떻게 다를까","fine":"오르막은 미는 힘, 내리막은 버티는 힘. 자연 길은 머리도 쉬게 한대요.","min":4,"k":[["−19%","내리막은 무릎이 일해요","−19% 내리막을 걸으면 무릎이 받는 힘이 평지보다 크게 늘었대요.","Kuster 1995"],["±15%","오르막·내리막은 반대","경사가 15%를 넘으면 오르막에선 근육이 밀고, 내리막에선 늘어나며 버틴대요.","Minetti 2002","hill"],["20~30%","힘을 아끼는 경사","산길은 경사 20~30%쯤이 높이 오르는 데 힘이 가장 덜 든대요.","Minetti 2002"],["90분","자연 길은 머리를 쉬게","자연 길을 90분 걸었더니 같은 생각을 곱씹는 게 줄었대요. 도시 길은 그대로였어요.","Bratman 2015"]],"sum":["내리막은 보폭 줄이고 천천히","오르막·내리막 섞어 걷기","가끔은 자연 길로"],"refs":["Kuster 외 1995, Clin Biomech","Minetti 외 2002, J Appl Physiol","Bratman 외 2015, PNAS"],"c":[],"qz":{"q":"자연 길 90분 걷기, 머리엔 어떨까?","a":["곱씹는 생각 ↓","그대로예요"],"ans":0,"why":"같은 생각을 곱씹는 게 줄었대요. 도시 길은 그대로였어요."},"oc":"산에서 오르막이랑 내리막 중 어디가 더 힘들던가요?"},{"id":"buy-running-shoes-afternoon","cat":"장비","tone":"paper","img":"shoe","w":["러닝화","오후에","사야 해?"],"cap":"러닝화는 왜 오후에 사라고 할까","fine":"앉아 있어도, 뛰고 나도 발이 부어요. 신발은 부은 발에 맞추기.","min":3,"k":[["14ml","앉아 있으면 붓는 발","하루 4시간 33분쯤 앉아 지낸 발이 14ml(약 3%) 부었다는 연구가 있어요.","BMC 2024"],["84.0","가만히 서 있으면","발목 핏줄 압력은 가만히 서 있을 때 84.0으로 제일 높았대요. 걸으면 23.5.","J Appl Physiol 1992","wave"],["걷기","붓게 하는 건 멈춤","같은 연구는 걷기가 발이 아래로 붓는 걸 막아 준다고 봤대요.","J Appl Physiol 1992"],["15분","뛰고 나면 한 번 더","15분 달린 뒤엔 걸은 뒤보다 발·발목이 더 부었대요. 건강하면 걱정할 일은 아니래요.","Cloughley·Mawdsley 1995","watch"]],"sum":["오후에 신어 보고 사기","러닝 양말 신고 피팅","틈틈이 일어나 걷기"],"refs":["Sitting foot 연구팀 2024, BMC Musculoskelet Disord","하지 정맥압 연구 1992, J Appl Physiol (PMID 1629057)","Cloughley·Mawdsley 1995, J Orthop Sports Phys Ther"],"c":[],"qz":{"q":"발을 붓게 하는 건 뭘까?","a":["걷기","가만히 멈춤"],"ans":1,"why":"걷기는 발이 아래로 붓는 걸 막아 준다고 봤대요."},"oc":"러닝화는 보통 하루 중 언제쯤 사러 가요?"},{"id":"hangover-next-day-run","cat":"런린이 가이드","tone":"paper","vert":["술먹고","뛰어도","될까"],"cap":"술 마신 다음 날 러닝, 해도 될까","fine":"숙취 땐 더 지치게 느껴진대요. 힘든 운동 뒤 술은 회복을 늦출 수 있어요.","min":3,"k":[["소변","술은 물을 빼요","술은 소변을 자주 나오게 해서 몸속 물이 빠지기 쉽대요. 뛰기 전엔 물부터.","Hobson·Maughan 2010","cup"],["299명","더 지쳤다고 느껴요","산길을 걸은 299명 중 숙취 있던 쪽이 더 지쳤다고 느꼈대요. 걸린 시간은 비슷했어요.","Samaria 협곡 연구"],["36·60시간","회복이 늦을 수 있어요","힘든 운동 뒤 술을 마시자 36·60시간 뒤에도 근육 힘이 더 떨어져 있었대요.","Barnes 2010","watch"]],"sum":["뛰기 전에 물 한 컵","평소보다 천천히, 짧게","힘든 날은 술 쉬어 가기"],"refs":["Hobson·Maughan 2010, Alcohol Alcohol","Relationship between Alcohol Hangover and Physical Endurance Performance: Walking the Samaria Gorge (PMC7019771)","Barnes·Mündel·Stannard 2010, J Sci Med Sport"],"c":[],"qz":{"q":"술은 몸속 물을 어떻게 할까?","a":["빼요","채워 줘요"],"ans":0,"why":"소변을 자주 나오게 해서 물이 빠지기 쉽대요."},"oc":"회식한 다음 날엔 러닝을 쉬는 편이에요?"},{"id":"first-exercise-where-to-start","cat":"런린이 가이드","tone":"paper","w":["운동 처음","뭐부터?"],"cap":"운동 처음이면 뭐부터 해야 할까","fine":"말하면서 할 수 있는 세기로 시작해요. 무릎이 걱정되면 물속·평지부터.","min":4,"k":[["토크 테스트","말로 재는 세기","편하게 말할 수 있으면 가벼운 세기, 말을 못 하면 센 거래요. 꽤 믿을 만한 방법이래요.","Sports Med 2022"],["−62%","물속에선 무릎이 가벼워","가슴 깊이 물에서 한 발로 서면 무릎에 걸리는 힘이 62% 줄었대요.","Kutzner 2017","wave"],["내리막","무릎에 제일 센 길","무릎 힘은 평지에서 가장 낮고, 같은 경사면 오르막보다 내리막이 더 컸대요.","Schwameder 2001"],["+17.1%","짧게 끊어 계단","대신 계단을 짧게 끊어 8주 오르자 숨 쓰는 힘이 17.1% 늘었대요.","계단 연구 PMID 16118293","steps"]],"sum":["말할 수 있는 세기로","무릎 걱정되면 물속·평지","처음 2주는 짧게"],"refs":["Talk Test 리뷰 2022, Sports Med","Kutzner 외 2017, PLOS ONE","Schwameder 외 2001, ISB 학회 초록","계단 오르기 연구, PubMed 16118293 · 24149477"],"c":[],"qz":{"q":"말하면서 할 수 있으면 운동 세기는?","a":["센 거","가벼운 거"],"ans":1,"why":"편하게 말할 수 있으면 가벼운 세기래요."},"oc":"운동을 처음 시작한다면 뭐부터 해 보고 싶어요?"},{"id":"daily-stairs-vs-weekend-hike","cat":"비교·대결","tone":"paper","w":["몰아서","해도돼?"],"img":"cal","cap":"매일 계단 15분 vs 주말 등산 3시간, 뭐가 나을까","fine":"체력은 몰아서 해도 나눠 해도 비슷하게 오른대요.","min":4,"k":[["+17%","계단 2분도 돼요","199계단(약 2분)을 주 5일, 8주 오르자 숨 쓰는 힘이 17% 올랐대요(15명).","Boreham 2005"],["주 2회","몰아서 해도 비슷","같은 양을 주 2회로 몰아서 해도, 주 4회로 나눠도 8주 뒤 체력은 비슷했대요.","Tripp 2025"]],"sum":["평일엔 계단 몇 분이라도","주말 등산은 그대로 즐기기","몰아서 해도 괜찮대요"],"refs":["Boreham 외 2005, Br J Sports Med","Tripp 외 2025, Scand J Med Sci Sports"],"c":[],"qz":{"q":"운동을 주말에 몰아서 해도 될까?","a":["O","X"],"ans":0,"why":"주 2회 몰아서 해도 8주 뒤 체력은 비슷했대요."},"oc":"매일 조금씩이 맞아요, 주말에 몰아서가 맞아요?"},{"id":"walk-10min-after-meal","cat":"몸속 이야기","tone":"paper","w":["밥 먹고","10분 걷기","효과?"],"cap":"밥 먹고 10분 걷기, 정말 효과 있을까","fine":"밥 먹고 바로 가볍게 걸으면, 앉아 있을 때보다 혈당이 덜 오른대요.","min":4,"k":[["걷기 > 서기","앉은 시간 끊기","오래 앉아 있다가 가볍게 걸으면 밥 먹고 혈당이 덜 올랐대요. 서 있기보다 나았어요.","Buffey 2022"],["0~30분","언제 걸을까","밥 먹고 0~30분 안에 움직여야 혈당이 덜 올랐대요. 밥 먹기 전엔 차이가 없었어요.","Engeroff 2023","watch"],["123 → 107분","위가 빨리 비어요","밥 먹고 천천히 걸었더니 위가 반쯤 비는 시간이 123분에서 107분으로 줄었대요.","Franke 2008"],["근육","당을 쓰는 곳","근육이 움직이면 당을 안으로 들이는 길이 열린대요. 그래서 가볍게 걸어도 돼요.","Richter·Hargreaves 2013"]],"sum":["밥 먹고 바로 10분 걷기","말하며 걷는 빠르기로","어지러우면 바로 멈추기"],"refs":["Buffey 외 2022, Sports Med","Engeroff 외 2023, Sports Med","Franke 외 2008, J Gastrointestin Liver Dis","Richter·Hargreaves 2013, Physiol Rev"],"c":[],"qz":{"q":"밥 먹고 언제 걸어야 혈당이 덜 오를까?","a":["밥 먹기 전","밥 먹고 30분 안"],"ans":1,"why":"밥 먹고 0~30분 안에 움직여야 덜 올랐대요."},"oc":"밥 먹고 나면 바로 걷는 편이에요, 앉아서 쉬는 편이에요?"},{"id":"hallasan-summit-body","cat":"몸속 이야기","tone":"paper","w":["한라산","오르면","몸속은?"],"cap":"한라산 정상까지 오르면 몸속에서 일어나는 일","fine":"오래 걸으면 연료가 지방 쪽으로 바뀌고, 간식이 버티는 시간을 늘린대요.","min":5,"k":[["1,947m","정상까지 9.6km","성판악(750m)에서 정상 1,947m까지 9.6km, 편도로 약 5시간 걸려요.","한라산국립공원"],["62%","오래 걸으면 지방을","오래 걸으면 연료가 바뀌어요. 가볍게 4시간 운동하자 지방이 62%까지 올랐대요.","Ahlborg 1974"],["3→4시간","간식이 버티게 해요","그래서 물만 마신 쪽은 3시간, 탄수화물을 먹은 쪽은 4시간 버텼대요(자전거 선수).","Coyle 1986"],["젖은 옷","쉴 땐 겉옷 입기","땀에 젖은 옷은 쉬는 동안 몸을 식혀요. 걸을 땐 벗고, 쉴 땐 입어요.","Castellani 2021","shirt"]],"sum":["진달래밭 통제 시간 확인","간식은 배고프기 전에","쉴 땐 바로 겉옷 입기"],"refs":["한라산국립공원 탐방안내, jeju.go.kr","Coyle 외 1986, J Appl Physiol","Ahlborg 외 1974, J Clin Invest","Castellani 외 2021, Curr Sports Med Rep"],"c":[],"qz":{"q":"오래 걸으면 몸 연료는 어느 쪽으로?","a":["지방 쪽","안 바뀌어요"],"ans":0,"why":"가볍게 4시간 운동하자 지방이 62%까지 올랐대요."},"oc":"한라산 정상, 올라가 봤어요? 아니면 가 보고 싶어요?"},{"id":"where-10000-steps-came-from","cat":"러닝 잡지식","tone":"paper","w":["만 보","누가","정했어?"],"cap":"하루 만 보는 어디서 나온 숫자일까","fine":"만 보는 일본 걷기 모임 구호에서 왔대요. 연구는 5천~7천 보 근처를 말해요.","min":3,"k":[["1960년대","만 보의 시작","만 보는 연구가 아니라 일본 걷기 모임과 회사 구호에서 나왔다고 알려져 있어요.","Tudor-Locke·Bassett 2004"],["5천~7천보","효과가 꺾이는 곳","연구 57편을 모아 보니 하루 5,000~7,000보쯤에서 효과가 꺾였대요.","Ding 2025","steps"],["7,500보","더 안 늘어난 지점","나이 든 여성 약 1만 6,700명을 보니 7,500보쯤에서 효과가 평평해졌대요.","Lee 2019"],["2천 → 4천","조금만 늘려도","하루 2,000보에서 4,000보로만 늘려도 건강에 좋은 쪽이었대요. 완벽보다 꾸준히.","Ding 2025 발표"]],"sum":["만 보 못 채워도 괜찮아요","지금보다 조금씩 늘리기","많이 걷는 날은 만 보도 OK"],"refs":["Tudor-Locke·Bassett 2004, Sports Med","Lee 외 2019, JAMA Intern Med","Ding 외 2025, Lancet Public Health"],"c":[],"qz":{"q":"하루 만 보는 연구에서 나온 숫자?","a":["O","X"],"ans":1,"why":"일본 걷기 모임과 회사 구호에서 나왔대요."},"oc":"하루 걸음 수, 평소에 세어 보는 편인가요?"},{"id":"lotte-tower-123-stairs","cat":"몸속 이야기","tone":"black","w":["롯데타워","계단","오르면?"],"cap":"롯데타워 123층 계단 오르면 몸속에서 생기는 일","fine":"2,917계단, 처음 서두르면 뒤에서 무너진대요. 같은 속도로 꾸준히가 답.","min":4,"k":[["2,917계단","1층에서 123층까지","롯데타워 계단 대회는 2,917계단이에요. 2026년 남자 1위는 16분 8초였대요.","뉴시스 2026"],["159","11층만 올라도","11층 180계단을 오르자 심박이 159까지 올랐대요. 꽤 센 운동 쪽이에요.","Teh·Aziz 2002","heart"],["316%","무릎이 받는 힘","무릎이 받는 힘이 평지 걷기 땐 몸무게의 261%, 계단 오를 땐 316%였대요.","Kutzner 2010"],["처음 천천히","서두르면 뒤에서 처져요","출발 때 서두른 사람은 뒤에서 갑자기 느려졌대요. 잘한 사람은 끝까지 일정했어요.","Minetti 2011"]],"sum":["첫 10층은 일부러 천천히","난간은 가볍게 잡고","같은 속도로 꾸준히"],"refs":["뉴시스 2026 · 머니투데이 2024 (대회 기사)","Teh·Aziz 2002, Med Sci Sports Exerc","Kutzner 외 2010, J Biomech","Minetti 외 2011, Scand J Med Sci Sports"],"c":[],"qz":{"q":"123층 계단, 처음에 서두르면?","a":["끝까지 빨라요","뒤에서 처져요"],"ans":1,"why":"서두른 사람은 뒤에서 갑자기 느려졌대요."},"oc":"123층 계단 오르기, 도전해 보고 싶은 마음 있어요?"},{"id":"bike-commute-30-days","cat":"몸속 이야기","tone":"paper","img":"cal","w":["자전거","출퇴근","몸 변화"],"cap":"자전거 출퇴근하면 몸은 어떻게 바뀔까","fine":"자전거는 무릎 힘이 걷기보다 작고, 몇 주 안에 피의 물 성분부터 는대요.","min":3,"k":[["걷기보다 작게","무릎 힘이 작아요","실내 자전거를 타면 무릎에 걸리는 힘이 걷기보다 작았대요. 땅을 딛지 않으니까요.","Kutzner 2012"],["빨리 돌리기","세게보다 가볍게","무릎 힘은 세게 밟을수록 커지고, 페달을 빨리 돌릴수록 줄었대요.","Kutzner 2012","pulse"],["허벅지·엉덩이","페달 미는 근육","페달은 다리 근육 여럿이 돌아가며 밀어요. 허벅지 앞과 엉덩이를 많이 써요.","Hug·Dorel 2009"],["2~4주","피의 물부터 늘어요","운동 시작 2~4주 동안 늘어나는 피는 거의 피의 물 성분이래요.","Convertino 1991","heart"]],"sum":["안장 높이부터 맞추기","가볍게 빨리 돌리기","헬멧·라이트, 이어폰 빼기"],"refs":["Kutzner 외 2012, J Orthop Sports Phys Ther","Hug·Dorel 2009, J Electromyogr Kinesiol","Convertino 1991, Med Sci Sports Exerc"],"c":[],"qz":{"q":"무릎 힘이 더 작은 쪽은?","a":["실내 자전거","걷기"],"ans":0,"why":"땅을 딛지 않으니 걷기보다 작았대요."},"oc":"출퇴근길을 자전거로 바꿀 수 있다면 해 볼래요?"},{"id":"runner-capillary-strength","cat":"몸속 이야기","tone":"paper","w":["실핏줄","몇개야?"],"cap":"오래 달리면 근육 속 실핏줄이 늘까","fine":"오래 달린 사람 근육엔 실핏줄이 촘촘하대요. 근력 운동 주 2일도 더해요.","min":4,"k":[["401개","오래 달리면 촘촘","허벅지 근육 1㎟ 속 실핏줄이 오래 달린 선수는 약 401개, 보통 사람은 306개였대요.","Tesch 1984"],["199개","굵은 근육은 성겨요","역도 선수는 약 199개로 더 적었대요. 근육이 굵어지면 실핏줄 사이가 넓어진대요.","Tesch 1984"],["주 2일","근력 운동도 같이","WHO는 숨찬 운동에 더해 근력 운동을 주 2일 이상 하라고 권해요.","WHO 2020","steps"],["손 안 짚고","앉았다 일어나기","바닥에 앉았다가 손 안 짚고 일어나기는 힘·유연성·균형을 한 번에 보는 테스트래요.","Brito 2014"]],"sum":["숨찬 달리기 주 150분부터","근력 운동 주 2일 끼우기","손 안 짚고 일어나 보기"],"refs":["Tesch 외 1984 (근육·실핏줄 비교 연구)","Bull 외 2020, Br J Sports Med (WHO 신체활동 지침)","Brito 외 2014, Eur J Prev Cardiol"],"c":[],"qz":{"q":"근육 속 실핏줄이 더 촘촘한 쪽은?","a":["역도 선수","오래 달린 선수"],"ans":1,"why":"오래 달린 선수는 약 401개, 역도 선수는 약 199개래요."},"oc":"러닝하면서 근력 운동도 같이 하고 있나요?"},{"id":"10000-steps-vs-brisk-30min","cat":"비교·대결","tone":"paper","w":["만 보 vs","빨리 30분"],"cap":"하루 만 보 vs 30분 빠르게 걷기, 뭐가 나을까","fine":"만 보는 하루를 고르게 채우고, 빠른 30분은 따로 챙기면 좋대요.","min":4,"k":[["9,505보","30분 쪽은 들쭉날쭉","30분 걷기 쪽은 걷는 날 9,505보, 안 걷는 날 5,597보로 차이가 컸대요.","Hultquist 2005"],["빠른 30분","걸음 수와 따로","하루 중 가장 빨랐던 30분이 빠를수록 좋은 쪽이었대요. 아직 연구마다 갈려요.","del Pozo Cruz 2022","pulse"]],"sum":["만 보 안에 빠른 30분 섞기","걷는 날, 안 걷는 날 차이 줄이기","틈틈이 일어나 걷기"],"refs":["Tudor-Locke 외 2019, Int J Behav Nutr Phys Act","Hultquist 외 2005, Med Sci Sports Exerc","del Pozo Cruz 외 2022, JAMA Intern Med"],"c":[],"qz":{"q":"30분 걷기만 하면 걸음 수는?","a":["날마다 비슷","날마다 들쭉날쭉"],"ans":1,"why":"걷는 날 9,505보, 안 걷는 날 5,597보였대요."},"oc":"만 보 채우기랑 30분 빠르게 걷기, 어느 쪽이 더 쉬워요?"},{"id":"lion-sleep-animal-myths","cat":"러닝 잡지식","tone":"paper","w":["사자는","안자거든"],"cap":"사자는 하루 종일 잔다? 동물 상식 오해","fine":"사자는 하루 41%쯤 움직였대요. 개는 헐떡임, 사람은 땀으로 식혀요.","min":4,"k":[["41%","사자는 꽤 움직여요","사자 무리를 보니 하루의 41%쯤 움직였대요. '하루 22시간 잔다'는 오해래요.","Hayward 2007"],["그늘","호랑이는 그늘부터","호랑이가 더위를 피할 때 가장 중요한 건 그늘이었대요. 물은 호랑이마다 달랐어요.","Stryker 2019","thermo"],["헐떡임","개는 숨으로 식혀요","개는 헐떡이며 혀와 숨길로 열을 내보내요. 그게 주된 식히는 방법이래요.","Goldberg 1981"],["10배","사람은 온몸으로 식혀요","사람 피부 땀샘은 침팬지보다 10배쯤 촘촘하대요. 땀이 마르며 온몸을 식혀요.","Kamberov 2018","shirt"]],"sum":["더운 날은 그늘 코스로","땀 잘 마르는 옷 입기","빨리보다 꾸준히"],"refs":["Hayward·Hayward 2007, Afr J Ecol","Stryker 외 2019, Int J Biometeorol","Goldberg 외 1981, Respir Physiol","Kamberov 외 2018, J Hum Evol"],"c":[],"qz":{"q":"사자는 하루 종일 잘까?","a":["O","X"],"ans":1,"why":"하루의 41%쯤 움직였대요. 오해래요."},"oc":"알고 보니 오해였던 동물 상식, 떠오르는 거 있어요?"},{"id":"new-runner-aches","cat":"런린이 가이드","tone":"black","w":["여기저기","쑤셔?"],"cap":"러닝 시작하고 아픈 근육통·옆구리, 흔한 일일까","fine":"근육통은 2~3일 뒤가 제일 심하고, 옆구리 통증은 흔한 일이래요.","min":4,"k":[["2~3일","근육통은 늦게 와요","근육통은 운동하고 바로가 아니라 2~3일 뒤에 가장 심했대요.","Clarkson 1992"],["6주","두 번째는 덜 아파요","같은 내리막 달리기를 3주나 6주 뒤 또 하면 근육통이 확실히 적었대요.","Byrnes 1985","hill"],["69%","옆구리 콕콕","러너 965명 중 69%가 1년 사이 뛰다가 옆구리가 아팠대요. 왜인지는 아직 몰라요.","Morton·Callister 2000"],["20.8≈20.3","천천히 늘려도 비슷","초보 532명을 천천히 늘린 쪽과 보통 쪽으로 나눴더니 다친 비율이 거의 같았대요.","Buist 2008","steps"]],"sum":["이틀째 더 아파도 놀라지 않기","거리는 천천히 늘리기","같은 곳이 계속 아프면 쉬기"],"refs":["Clarkson 외 1992, Med Sci Sports Exerc","Byrnes 외 1985, J Appl Physiol","Morton·Callister 2000, Med Sci Sports Exerc","Buist 외 2008, Am J Sports Med"],"c":[],"qz":{"q":"근육통이 가장 심한 때는?","a":["운동 바로 뒤","2~3일 뒤"],"ans":1,"why":"운동하고 바로가 아니라 2~3일 뒤래요."},"oc":"러닝 처음 시작했을 때 제일 낯설었던 건 뭐였어요?"},{"id":"max-heart-rate-220-age","cat":"런린이 가이드","tone":"paper","w":["220−나이","맞아?"],"cap":"최대 심박수 220−나이 맞을까 · 나이와 심폐 체력","fine":"220−나이는 대략값이래요. 그래도 몸은 몇 살이든 운동에 반응해요.","min":4,"k":[["208−0.7×나이","더 맞는 공식","연구 351편을 모아 보니 최고 심박은 208−0.7×나이에 가까웠대요. 60세면 166.","Tanaka 2001"],["3~6%","10년마다 줄어요","심폐 능력은 10년마다 20·30대엔 3~6%씩, 70대 넘으면 20% 넘게 줄었대요.","Fleg 2005","pulse"],["50세","다리 근육은 50세쯤","근육이 뚜렷이 줄기 시작한 건 50세 무렵, 주로 다리 쪽이었대요.","Janssen 2000"],["257→310","60대도 실핏줄이 늘어요","그래도 64세쯤에 9~12개월 걷고 뛰자 다리 실핏줄이 257개→310개로 늘었대요.","Coggan 1992"]],"sum":["심박보다 숨차는 느낌으로","하체 근력 운동 더하기","몇 살이든 지금 시작"],"refs":["Tanaka·Monahan·Seals 2001, J Am Coll Cardiol","Fleg 외 2005, Circulation","Janssen 외 2000, J Appl Physiol","Coggan 외 1992, J Appl Physiol"],"c":[],"qz":{"q":"최고 심박 220−나이, 딱 맞을까?","a":["O","X"],"ans":1,"why":"대략값이래요. 208−0.7×나이에 더 가까웠대요."},"oc":"달릴 때 심박수를 챙겨 보는 편인가요?"},{"id":"how-much-water-while-running","cat":"몸속 이야기","tone":"paper","img":"road","w":["물","벌컥벌컥","괜찮아?"],"cap":"달리면서 물 얼마나 마셔야 할까","fine":"너무 적게도, 너무 많이도 문제래요. 오래 뛸수록 조심해요.","min":3,"k":[["4%","물이 빠지면","몸무게의 4%만큼 물이 빠진 채 더위에 뛰자 심장이 보내는 피가 13% 줄었대요.","González-Alonso 1997"],["13%","많이 마셔도 문제","보스턴 마라톤 완주자 488명 중 13%는 피 속 소금기가 너무 묽어졌대요.","Almond 2005","cup"],["4시간+","오래 뛸수록 조심","소금기가 묽어지는 일은 4시간 넘게 뛴 사람에게 더 많았대요.","Almond 2005"],["39℃","더운 날 하프 거리","더운 날 21km를 뛴 군인 18명 모두 몸속 온도가 39℃를 넘었대요.","Byrne 2006","thermo"]],"sum":["목마를 때 몇 모금씩","몸무게 늘 만큼 마시지 않기","더운 날은 느리게"],"refs":["González-Alonso 외 1997, J Appl Physiol","Almond 외 2005, N Engl J Med","Byrne 외 2006, Med Sci Sports Exerc"],"c":[],"qz":{"q":"달릴 때 물은 많이 마실수록 좋을까?","a":["O","X"],"ans":1,"why":"보스턴 완주자 13%는 피 속 소금기가 너무 묽어졌대요."},"oc":"달리러 나갈 때 물을 챙겨 가요, 그냥 나가요?"},{"id":"brisk-walk-cadence-100","cat":"런린이 가이드","tone":"paper","w":["10초에","17걸음"],"img":"shoe","cap":"빠르게 걷기 기준, 1분에 몇 걸음이면 될까","fine":"1분 100걸음부터 중간 세기래요. 10초에 17걸음이면 넘어요.","min":3,"k":[["100걸음","1분 100걸음부터","1분에 100걸음을 넘기면 중간 세기래요. 가만히 있을 때보다 산소를 세 배쯤 써요.","Tudor-Locke 2019"],["10초 17걸음","세는 법은 간단","1분 100걸음을 10초로 줄이면 약 17걸음이래요. 걷다가 10초만 세어 보면 돼요.","Tudor-Locke 2019","watch"],["130걸음","130걸음이면 센 운동","1분 130걸음쯤이면 가만히 있을 때의 여섯 배, 센 세기 쪽이래요.","Tudor-Locke 2019"],["시속 8km","빠를수록 숨이 커요","같은 거리를 걸어도 시속 8km로 걸은 쪽이 숨 쓰는 힘이 가장 많이 늘었대요.","Duncan 1991","steps"]],"sum":["10초에 17걸음 세어 보기","출근길 몇 분은 빠르게","숨이 조금 차는 빠르기로"],"refs":["Tudor-Locke 외 2019, Int J Behav Nutr Phys Act","Duncan·Gordon·Scott 1991, JAMA"],"c":[],"qz":{"q":"1분 100걸음 넘기면 중간 세기일까?","a":["O","X"],"ans":0,"why":"10초에 17걸음쯤이면 넘는대요."},"oc":"빠르게 걸을 때 1분 걸음 수, 한번 세어 볼래요?"},{"id":"heavy-7-vs-light-20","cat":"비교·대결","tone":"black","w":["무겁게vs","가볍게","근육 커?"],"cap":"무겁게 7번 vs 가볍게 20번, 근육은 어느 쪽이 클까","fine":"무겁게 들면 끝까지 안 가도 되고, 가볍게 들면 끝까지 가야 컸대요.","min":4,"k":[["7.7 vs 2.8","중간에 멈췄을 때","무겁게 7번쯤 멈춘 다리는 7.7% 굵어졌대요. 가볍게 20번쯤 멈추면 2.8%뿐이었어요.","Lasevicius 2022"],["마지막 3~5회","끝까지 들면","왜 그럴까요? 가볍게 끝까지 들면 마지막 3~5회에 근육 신호가 가장 커졌대요.","Sundstrup 2012","pulse"],["33 vs 16%","힘은 무거운 쪽","대신 드는 최대 무게는 무겁게 한 다리가 33%쯤, 가볍게는 16~18%쯤 늘었대요.","Lasevicius 2022"],["3~5주","처음엔 뇌가 배워요","처음 몇 주 느는 힘은 뇌가 드는 법을 먼저 배운 덕이 크다는 연구가 있어요.","Moritani·deVries 1979"]],"sum":["가볍게 들면 끝까지 가까이","힘을 키우려면 무겁게","처음 몇 주는 뇌가 배워요"],"refs":["Lasevicius 외 2022, J Strength Cond Res","Sundstrup 외 2012, J Strength Cond Res","Moritani·deVries 1979, Am J Phys Med"],"c":[],"qz":{"q":"중간에 멈출 때 더 굵어진 쪽은?","a":["무겁게 7번","가볍게 20번"],"ans":0,"why":"무겁게는 7.7%, 가볍게는 2.8%뿐이었대요."},"oc":"근력 운동은 무겁게 적게 해요, 가볍게 많이 해요?"},{"id":"jump-rope-tendon-3weeks","cat":"몸속 이야기","tone":"paper","w":["힘줄아","기다려"],"cap":"줄넘기 3주, 바로 늘려도 될까 · 근육과 힘줄의 시간차","fine":"근육은 3~4주면 바뀌지만 힘줄은 한두 달 늦게 따라온대요.","min":4,"k":[["3~4주","근육은 빨리 바뀌어요","근육은 센 운동 3~4주 만에 바뀔 수 있대요. 힘줄은 그렇게 빠르지 않대요.","Mersmann 2017"],["2달","힘줄은 아직 그대로","그런데 발목 뒤 힘줄은 운동 2달까지 단단함이 그대로였다는 연구가 있어요.","Kubo 2012","rope"],["+50.3%","3달 끝에 달라져요","같은 연구에서 힘줄 단단함은 3달 끝에야 50.3% 늘었대요.","Kubo 2012 · Bohm 2015"],["1~2달","이 틈에 탈 나기 쉬워요","그래서 힘이 힘줄보다 1~2달 먼저 느는 그 틈에 탈 날 수 있다고 봐요.","Mersmann 2017","shin"]],"sum":["편해져도 양은 천천히","발목 뒤 뻐근하면 쉬기","딱딱한 바닥은 피하기"],"refs":["Mersmann·Bohm·Arampatzis 2017, Front Physiol","Kubo 외 2012, Eur J Appl Physiol","Bohm 외 2015, Sports Med Open"],"c":[],"qz":{"q":"더 빨리 바뀌는 건 뭘까?","a":["힘줄","근육"],"ans":1,"why":"근육은 3~4주, 힘줄은 3달 끝에야 달라졌대요."},"oc":"운동량은 한 번에 확 늘리는 편이에요, 천천히 늘리는 편이에요?"}];
